ocumentElement.dataset.dlMotion; // 跟状态栏走\n  if (m) return m === 'full' ? 'full' : m === 'off' ? 'off' : 'lite';\n  try { return W.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'lite' : 'full'; } catch (_) { return 'full'; }\n}\n// 动画循环每帧都要看档位：记一份，档位真变了（设置、状态栏、系统“减少动态”）再更新\nlet curMotion = 'full';\nfunction syncMotion() { curMotion = motion(); if (phone && phone.dataset.motion !== curMotion) phone.dataset.motion = curMotion; return curMotion; }\n\n/* ───────── 聊天记录（聊天变量） ───────── */\nconst blankStore = () => ({ v: 1, mid: 1, convs: {}, groups: [], order: [], blocked: {}, known: {}, manual: {}, proLast: -1, para: { posts: [], dms: {}, verdicts: [], lastFloor: -1, fresh: 0 }, gfChat: { msgs: [], packets: [], unread: 0, seeded: false } });\nfunction loadStore() {\n  let s = null;\n  storeChat = chatNow();\n  try { s = H.loadStore(); } catch (_) { s = null; }\n  store = Object.assign(blankStore(), s && typeof s === 'object' ? s : {});\n  store.para = Object.assign(blankStore().para, store.para || {});\n  store.gfChat = Object.assign(blankStore().gfChat, store.gfChat && typeof store.gfChat === 'object' ? store.gfChat : {});\n  if (!Array.isArray(store.gfChat.msgs)) store.gfChat.msgs = [];\n  if (!Array.isArray(store.gfChat.packets)) store.gfChat.packets = [];\n  ['convs', 'blocked', 'known', 'manual'].forEach((k) => { if (!store[k] || typeof store[k] !== 'object') store[k] = {}; });\n  if (!Array.isArray(store.groups)) store.groups = [];\n  if (!Array.isArray(store.order)) store.order = [];\n}\nlet saveT = null;\nfunction save() {\n  if (saveT) clearTimeout(saveT);\n  saveT = later(500, () => { saveT = null; if (chatNow() !== storeChat) return; prune(); try { H.saveStore(store); } catch (e) { console.warn('[斗罗小手机] 聊天记录保存失败', e); } inject(); });\n}\n// 存进聊天文件前收一收：每段对话留最近 400 条；真图只留最近 30 张（更早的只留描述，换成画出来的底图）\nconst KEEP_MSGS = 400, KEEP_PICS = 30;\nfunction prune() {\n  const lists = [...Object.values(store.convs), ...store.groups, ...Object.values(store.para.dms)].map((c) => c.msgs).filter(Array.isArray);\n  lists.forEach((l) => { if (l.length > KEEP_MSGS) l.splice(0, l.length - KEEP_MSGS); });\n  if (store.gfChat) {\n    if (Array.isArray(store.gfChat.msgs) && store.gfChat.msgs.length > 200) store.gfChat.msgs.splice(0, store.gfChat.msgs.length - 200);\n    if (Array.isArray(store.gfChat.packets) && store.gfChat.packets.length > 24) store.gfChat.packets.length = 24;\n  }\n  const pics = lists.flat().filter((m) => m.k === 'img' && m.src).sort((a, b) => (+String(b.id).slice(1) || 0) - (+String(a.id).slice(1) || 0));\n  pics.slice(KEEP_PICS).forEach((m) => { delete m.src; m.pic = picOf(m.x); });\n}\nconst newId = () => 'm' + (store.mid++);\n\n/* ───────── 人物（读 MVU 变量） ───────── */\nconst ents = (o) => (o && typeof o === 'object' ? Object.entries(o) : []);\nconst textOf = (...xs) => xs.map((x) => (Array.isArray(x) ? x.join('、') : x && typeof x === 'object' ? Object.keys(x).join('、') : x || '')).join(' ');\nfunction barAvatars() { try { return (JSON.parse(W.localStorage.getItem(BAR_KEY) || '{}').avatars) || {}; } catch (_) { return {}; } }\nfunction faceOf(name, person) {\n  const mine = barAvatars()[name];\n  if (mine && mine.src) return mine.src;\n  const lib = W.DLAvatars;\n  if (!lib || !name) return null;\n  const ctx = { part: D.world.part, age: person && person.年龄, choice: mine && mine.pick };\n  try { const shown = shownName(name, person); const hit = (shown !== name && lib.pick(shown, ctx)) || lib.pick(name, ctx); return hit ? hit.src : null; } catch (_) { return null; }\n}\nfunction shownName(name, person) {\n  const lib = W.DLAvatars, t = (stat && stat.时空) || {};\n  if (!lib || typeof lib.persona !== 'function') return (person && person.称呼) || name;\n  try { return lib.persona(name, { part: t.当前部, date: t.外界日期, call: person && person.称呼 }) || name; } catch (_) { return name; }\n}\nconst soulOf = (p) => { const list = ents(p.武魂).filter(([, w]) => w && w.形态 !== '血脉'); return (list.find(([, w]) => w.使用中) || list[0] || [null, null]); };\nfunction ringsOf(p) {\n  const [, w] = soulOf(p);\n  if (w && Array.isArray(w.魂环) && w.魂环.length) return w.魂环;\n  return p.修为年限 ? [{ 年限: p.修为年限, 凶兽: p.凶兽 }] : [];\n}\nconst rankRing = (x) => (x.神级 ? 1e12 : x.凶兽 ? 1e10 : typeof x.年限 === 'number' ? x.年限 : x.魂环颜色 || x.特殊色 ? 1e9 : 0);\nconst topRingOf = (rs) => rs.reduce((b, r) => (!b || rankRing(r) >= rankRing(b) ? r : b), null);\nconst DEAD = /身亡|死亡|陨落|战死|阵亡|身故|殒命|殒落|牺牲|魂飞魄散|已死/u;\nconst COMA = /昏迷|昏厥|昏死|不省人事|失去意识|晕厥|晕过去|假死/u;\nconst FIGHT = /交战|激战|鏖战|厮杀|战斗中|对决中|迎战|围攻|搏杀/u;\nconst BUSY = /修炼|闭关|冥想|打坐|吸收魂环|突破|入定|疗伤/u;\nfunction stateOf(name, p) {\n  const fight = stat && stat.战斗 && stat.战斗.交战中 && ((stat.战斗.我方 || []).includes(name) || ents(stat.战斗.对手).some(([n]) => n === name));\n  const eff = textOf(p.伤势, p.自动状态, p.生效状态, p.行动);\n  if (DEAD.test(eff)) return ['dead', '已沉寂'];\n  if ((p.资源 && p.资源.气血 === 0) || COMA.test(eff)) return ['coma', '失去意识' + (p.位置 ? ' · ' + p.位置 : '')];\n  if (fight || FIGHT.test(p.行动 || '')) return ['fight', '交战中' + (p.行动 ? ' · ' + p.行动 : '')];\n  if (BUSY.test(p.行动 || '')) return ['busy', (p.行动 || '修炼中') + ' · 回复会慢一些'];\n  return ['ok', ''];\n}\nfunction personFrom(name, p, archived) {\n  const rs = archived ? [] : ringsOf(p);\n  const [soulName] = archived ? [''] : soulOf(p);\n  const has = !!(p && p.联系方式) || !!store.manual[name];\n  let state = 'ok', stateText = '';\n  if (archived) { [state, stateText] = DEAD.test(archived.结局 || '') ? ['dead', '已沉寂'] : ['gone', '联系不上']; }\n  else if (!has && !store.known[name]) state = 'none';\n  else [state, stateText] = stateOf(name, p);\n  if (state !== 'none' && state !== 'dead' && state !== 'gone' && store.blocked[name]) { state = 'block'; stateText = '已将你拉黑'; }\n  const o = {\n    id: name, key: name, name: shownName(name, p), real: name, av: faceOf(name, p), title: (p && p.称号) || '', lv: (p && p.魂力等级) || 0,\n    soul: soulName || (p && p.种族) || '', rings: rs, top: topRingOf(rs), aff: p && typeof p.好感度 === 'number' ? p.好感度 : 0, love: p && typeof p.情意 === 'number' && p.情意 > 0 ? p.情意 : null,\n    tags: (p && p.关系标签) || (archived ? [archived.关系 || ''] : []), where: (p && p.位置) || '—', doing: (p && p.行动) || '—', mood: (p && p.情绪) || '—',\n    state, stateText, sign: (p && p.身份) || '', poke: '的肩膀', met: (p && (p.关系标签 || []).join(' · ')) || '认识但没有联系方式', here: !!(p && p.在场),\n    ending: archived ? archived.结局 : '', raw: p || null,\n  };\n  return o;\n}\n// 从最新变量重建人物表；返回这次变化（新交换联系方式、拉黑解除）给提示用\nfunction rebuildPeople() {\n  const h = (stat && stat.主角) || {}, t = (stat && stat.时空) || {};\n  const [hs, hw] = soulOf(h);\n  const date = t.外界日期 || '';\n  const m = /(\\d{1,2})月(\\d{1,2})日/u.exec(date);\n  D = {\n    hero: { name: h.姓名 || '我', title: h.称号 || '', lv: h.魂力等级 || 0, soul: hs || h.种族 || '', 魂力: h.资源 && typeof h.资源.魂力 === 'number' ? h.资源.魂力 : 100, rings: ringsOf(h), raw: h },\n    world: { date: date || '日期未定', md: m ? `${m[1].padStart(2, '0')}·${m[2].padStart(2, '0')}` : '——', part: t.当前部 || null, act: t.当前幕 || (stat && stat.原作指导 && stat.原作指导.幕) || '', place: t.地点 || '' },\n    people: [],\n  };\n  void hw;\n  const seen = new Set(), news = [];\n  for (const [name, p] of ents(stat && stat.人物)) {\n    if (!name || name === D.hero.name) continue;\n    const o = personFrom(name, p, null);\n    if (o.state !== 'none' && !store.known[name]) { store.known[name] = true; if (stat) news.push(o); }\n    D.people.push(o); seen.add(name);\n  }\n  for (const [name, a] of ents(stat && stat.人物归档)) if (!seen.has(name) && store.known[name]) { D.people.push(personFrom(name, null, a)); seen.add(name); }\n  // 聊过但变量里已经没有的人（换部、删档）：保留成“联系不上”\n  const talked = new Set([...Object.keys(store.convs).filter((k) => k.startsWith('dm:')).map((k) => k.slice(3)), ...store.groups.flatMap((g) => g.members || [])]);\n  for (const name of talked) if (!seen.has(name)) { D.people.push(personFrom(name, null, { 结局: '', 关系: '' })); seen.add(name); }\n  for (const name of Object.keys(store.para.dms || {})) if (!seen.has(name)) { const o = personFrom(name, null, { 结局: '', 关系: '' }); o.state = 'ok'; o.paraOnly = true; D.people.push(o); seen.add(name); }\n  // 好感回到陌路以上自动解除拉黑\n  let dirty = news.length > 0;\n  for (const o of D.people) if (store.blocked[o.id] && o.raw && o.aff > -21) { dirty = true; delete store.blocked[o.id]; o.state = stateOf(o.id, o.raw)[0]; sysQuiet('dm:' + o.id, `${o.name} 把你从黑名单里放了出来。`); }\n  byId = Object.fromEntries(D.people.map((p) => [p.id, p]));\n  for (const o of news) {\n    if (!store.convs['dm:' + o.id]) { store.convs['dm:' + o.id] = { unread: 0, msgs: [] }; store.order.unshift('dm:' + o.id); sysQuiet('dm:' + o.id, `你和 ${o.name} 在正文里交换了联系方式。现在可以发消息了。`); }\n    if (phone) toast({ av: av(o, 'sm'), t: '名册多了一个人', x: `正文里你和 ${o.name} 互留了联系方式。`, go: ['chat', 'dm:' + o.id] });\n  }\n  if (dirty) save();\n  // 顺序表补齐、去掉失效的\n  const valid = (k) => (k.startsWith('dm:') ? !!byId[k.slice(3)] : k.startsWith('g:') ? store.groups.some((g) => 'g:' + g.id === k) : false);\n  store.order = [...new Set(store.order.filter(valid))];\n  for (const k of Object.keys(store.convs)) if (k.startsWith('dm:') && valid(k) && !store.order.includes(k)) store.order.push(k);\n  for (const g of store.groups) if (!store.order.includes('g:' + g.id)) store.order.push('g:' + g.id);\n}\nconst ghost = (id) => ({ id, name: id, real: id, av: faceOf(id, null), title: '', lv: 0, soul: '', rings: [], top: null, aff: 0, love: null, tags: [], where: '—', doing: '—', mood: '—', state: 'gone', stateText: '联系不上', sign: '', poke: '', met: '', ending: '' });\nconst person = (id) => byId[id] || ghost(id);\n\n/* ───────── 会话 ───────── */\nfunction conv(key) {\n  const i = key.indexOf(':'), t = key.slice(0, i), id = key.slice(i + 1);\n  let c;\n  if (t === 'dm') { c = store.convs[key] || (store.convs[key] = { unread: 0, msgs: [] }); def(c, 'type', 'dm'); def(c, 'p', person(id)); }\n  else if (t === 'g') { c = store.groups.find((g) => g.id === id) || { id, name: '已解散的群', members: [], msgs: [], unread: 0 }; def(c, 'type', 'group'); }\n  else if (t === 'pd') { c = store.para.dms[id] || (store.para.dms[id] = { unread: 0, msgs: [] }); def(c, 'type', 'pdm'); def(c, 'p', Object.assign({}, person(id), { state: 'ok' })); }\n  else { c = store.para.posts.find((p) => p.id === id) || { id, tag: '已删', title: '帖子不见了', body: '', cms: [] }; if (!Array.isArray(c.cms)) c.cms = []; def(c, 'type', 'post'); def(c, 'msgs', c.cms); }\n  if (!Array.isArray(c.msgs)) c.msgs = [];\n  def(c, 'key', key);\n  return c;\n}\nconst now = () => { const d = new Date(); return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); };\nconst unreadMsg = () => store.order.reduce((n, k) => n + (conv(k).unread || 0), 0);\nconst unreadPara = () => Object.values(store.para.dms).reduce((n, c) => n + (c.unread || 0), 0) + (store.para.fresh || 0);\n\n/* ───────── 小零件 ───────── */\nfunction ringStyleOf(r) {\n  if (!r) return '';\n  const o = RP.look(r);\n  return `--rc:${o.main};--rg:${o.hint > 0.15 ? o.glow : o.stops.length > 1 ? o.second : o.main}`;\n}\nfunction heroFace() { const h = D.hero; const mine = barAvatars()[h.name]; if (mine && mine.src) return mine.src; try { const p = H.personaAvatar(); if (p) return p; } catch (_) { /* 没有 */ } return faceOf(h.name, h.raw); }\nfunction av(p, cls = '') {\n  if (p === 'me') { const src = heroFace(); return `<span class=\"dp-av me ${cls}\" style=\"${ringStyleOf(topRingOf(D.hero.rings || []))}\">${src ? `<img src=\"${esc(src)}\" alt=\"\" draggable=\"false\">` : `<b>${esc(first(D.hero.name))}</b>`}<i class=\"dp-av-r\"></i></span>`; }\n  const o = typeof p === 'string' ? person(p) : p;\n  if (!o) return `<span class=\"dp-av anon ${cls}\"><b>？</b><i class=\"dp-av-r\"></i></span>`;\n  const inner = o.av ? `<img src=\"${esc(o.av)}\" alt=\"\" draggable=\"false\">` : `<b>${esc(first(o.name))}</b>`;\n  return `<span class=\"dp-av s-${o.state} ${cls}\" data-pid=\"${esc(o.id)}\" style=\"${ringStyleOf(o.top)}\">${inner}<i class=\"dp-av-r\"></i><i class=\"dp-av-s\"></i></span>`;\n}\nconst rings = (p) => `<span class=\"dp-rings\">${(p.rings || []).map((r, i) => { const o = RP.look(r); return `<i class=\"${o.rainbow ? 'rb' : ''}\" style=\"--rc:${o.main};--rg:${o.hint > 0.15 ? o.glow : o.second};--i:${i};border-color:${RP.border4(o)}\" title=\"第${i + 1}魂环 · ${esc(r.年限 != null ? r.年限 + '年' : '')} ${esc(o.name)}\"></i>`; }).join('')}</span>`;\nconst chip = (p) => { const s = STATE[p.state] || STATE.ok; return `<span class=\"dp-chip s-${p.state}\">${s.ic ? ic(s.ic) : '<i class=\"dp-dot\"></i>'}${esc(p.state === 'ok' ? s.t : (p.stateText || s.t).split(' · ')[0])}</span>`; };\nconst fmt = (x) => esc(x).replace(/@\\S+/gu, (m) => `<b class=\"dp-at\">${m}</b>`).replace(/\\n/g, '<br>');\nconst who = (o, para) => (o ? esc(o.name) + (para ? '<i class=\"dp-ol\">原线</i>' : '') : '');\n// 图：玩家发的是真图；角色发的是“画面描述”，按关键词配一张画出来的底图\nconst PICS = [[/森林|林间|树|山谷|草/u, 'forest'], [/湖|水|海|河|泉|雨/u, 'lake'], [/城|街|夜市|灯|楼|宫/u, 'city'], [/黄昏|晚霞|夕阳|日落|操场/u, 'dusk']];\nconst picOf = (x) => { const hit = PICS.find(([re]) => re.test(x || '')); return hit ? hit[1] : ['dusk', 'forest', 'lake', 'city'][Math.abs([...String(x || '')].reduce((a, ch) => a + ch.codePointAt(0), 0)) % 4]; };\n\nfunction bubble(m, c, fresh) {\n  if (m.f === 'sys') return `<div class=\"dp-sys ${m.rc ? 'rc' : ''} ${fresh ? 'fresh' : ''}\" data-mid=\"${m.id}\"><span>${esc(m.x)}</span>${m.rc && m.rc.x && !m.rc.k ? '<button class=\"dp-reedit\" type=\"button\" data-act=\"reedit\">重新编辑</button>' : ''}</div>`;\n  const me = m.f === 'me', p = me ? null : person(m.f), para = c.type === 'pdm';\n  const name = !me && c.type === 'group' ? `<em class=\"dp-who\">${who(p)}</em>` : '';\n  const body = m.k === 'img'\n    ? `<figure class=\"dp-pic\" ${m.src ? `style=\"background-image:url('${esc(m.src)}')\"` : `data-pic=\"${m.pic || picOf(m.x)}\"`}>${m.x ? `<figcaption>${esc(m.x)}</figcaption>` : ''}</figure>`\n    : `<p>${fmt(m.x)}</p>`;\n  const st = me && m.st ? `<span class=\"dp-st st-${m.st}\">${ST[m.st]}</span>` : '';\n  const flag = me && (m.st === 'block' || m.st === 'fail') ? '<i class=\"dp-flag\">!</i>' : '';\n  const ops = `<span class=\"dp-ops\">${opsHtml(m)}</span>`;\n  return `<div class=\"dp-msg ${me ? 'me' : 'them'} ${m.k === 'img' ? 'is-img' : ''} ${fresh ? 'fresh' : ''}\" data-mid=\"${m.id}\">${me ? '' : av(p, 'sm')}<div class=\"dp-bw\">${name}<div class=\"dp-bub\">${body}<i class=\"dp-bub-o\"></i></div><div class=\"dp-meta\"><time>${esc(m.tm || '')}</time>${st}</div></div>${flag}${ops}</div>`;\n}\n// 点开气泡后的小按钮：自己的消息看状态给“撤回 / 重发 / 再发”，别人的给“重说”\nfunction opsHtml(m) {\n  const b = (act, icon, label, tip) => `<button type=\"button\" data-act=\"${act}\" title=\"${tip || label}\">${ic(icon)}<span>${label}</span></button>`;\n  if (m.f !== 'me') return b('regen', 'redo', '重说', '让 TA 重说一遍') + b('delmsg', 'trash', '删除', '删掉这条');\n  const out = [];\n  if (recallable(m)) out.push(b('recall', 'undo', '撤回', '撤回这条（对方看到的是“撤回了一条消息”）'));\n  if (UNDELIVERED.includes(m.st)) out.push(b('resend', 'send', '重发', '挪到最下面重新发一次'));\n  else if (!WAITING.includes(m.st)) out.push(b('resend', 'send', '再发', '把这条再发一次'));\n  out.push(b('delmsg', 'trash', '删除', '删掉这条（只删你这边的记录）'));\n  return out.join('');\n}\n// 按游戏日期分段\nfunction msgsHtml(c) {\n  let day = null; const out = [];\n  for (const m of c.msgs) { const d = m.date || D.world.date; if (d !== day) { day = d; out.push(`<div class=\"dp-day\"><span>${esc(d)}</span></div>`); } out.push(bubble(m, c)); }\n  if (!c.msgs.length) out.push(`<div class=\"dp-day\"><span>${esc(D.world.date)}</span></div>`);\n  return out.join('');\n}\nfunction hd(o) {\n  const back = o.back === undefined ? true : o.back;\n  return `<header class=\"dp-hd ${o.cls || ''}\">${back ? `<button class=\"dp-hb dp-back\" data-act=\"back\" aria-label=\"返回\">${ic('back')}</button>` : ''}${o.left || ''}<div class=\"dp-hd-t\" ${o.go ? `data-go=\"${esc(o.go)}\"` : ''}><b>${o.title}</b>${o.sub ? `<span>${o.sub}</span>` : ''}</div><div class=\"dp-hd-r\">${o.right || ''}</div><i class=\"dp-hd-o\"></i></header>`;\n}\nconst topBack = () => S.shell === 'home';\nfunction composer(key, ph, inj) {\n  return `<footer class=\"dp-ft\">${inj ? `<button class=\"dp-inj ${S.set.inject ? 'on' : ''}\" data-act=\"inj\">${ic('link')}<span>最近 <b>${S.set.per}</b> 条会写进正文上下文</span><i class=\"dp-sw\"></i></button>` : ''}\n    <div class=\"dp-tray\" hidden><button data-act=\"pickimg\">${ic('img')}<span>发图片</span></button>${inj ? `<button data-act=\"pokeit\">${ic('like')}<span>拍一拍</span></button>` : ''}<button data-act=\"nudge\">${ic('redo')}<span>催一下</span></button></div>\n    <form class=\"dp-cmp\" data-key=\"${esc(key)}\"><button type=\"button\" class=\"dp-cb\" data-act=\"tray\" aria-label=\"更多\">${ic('plus')}</button><textarea rows=\"1\" placeholder=\"${esc(ph)}\" enterkeyhint=\"send\"></textarea><button type=\"submit\" class=\"dp-send\" aria-label=\"发送\">${ic('send')}<i></i></button></form></footer>`;\n}\n\n/* ───────── 各屏 ───────── */\nfunction preview(c) {\n  const last = c.msgs.filter((m) => m.f !== 'sys' || m.rc).slice(-1)[0];\n  if (!last) return c.type === 'dm' ? esc((STATE[c.p.state] || STATE.ok).t) : '';\n  if (last.rc) return esc(last.x);\n  const t = last.k === 'img' ? '[图片] ' + (last.x || '') : last.x;\n  const pre = last.f === 'me' ? (last.st === 'block' ? '[被拒收] ' : last.st === 'fail' ? '[未送达] ' : last.st === 'unseen' ? '[未读] ' : '') : c.type === 'group' ? person(last.f).name + '：' : '';\n  return esc(pre + t);\n}\nfunction row(key) {\n  const c = conv(key), g = c.type === 'group', p = c.p, last = c.msgs.slice(-1)[0];\n  const face = g ? `<span class=\"dp-gav\">${c.members.slice(0, 4).map((id) => av(id, 'xs')).join('')}</span>` : av(p);\n  const mark = !g && p.state !== 'ok' ? `<i class=\"dp-mk s-${p.state}\">${ic((STATE[p.state] || STATE.ok).ic)}</i>` : '';\n  return `<button class=\"dp-row ${c.unread ? 'has-new' : ''} ${c.pin ? 'pinned' : ''}\" data-go=\"${g ? 'group' : 'chat'}:${esc(key)}\">${face}\n    <span class=\"dp-row-m\"><b>${esc(g ? c.name : p.name)}${g ? `<i class=\"dp-n\">${c.members.length + 1}</i>` : ''}${mark}</b><span class=\"dp-row-p\">${preview(c)}</span></span>\n    <span class=\"dp-row-r\"><time>${esc((last && last.tm) || '')}</time>${c.unread ? `<i class=\"dp-badge\">${c.unread}</i>` : c.pin ? ic('pin', 'dp-pinic') : ''}</span></button>`;\n}\nconst cm = (c, fresh) => `<div class=\"dp-cm ${c.by === 'me' ? 'me' : ''} ${fresh ? 'fresh' : ''}\">${av(c.by === 'me' ? 'me' : c.by, 'sm')}<div><em>${c.by === 'me' ? esc(D.hero.name) + '<i class=\"dp-ol here\">此线</i>' : c.by ? who(person(c.by), 1) : esc(c.anon || '匿名')}</em><p>${esc(c.x)}</p><time>${esc(c.tm || '刚刚')}</time></div></div>`;\nconst SCR = {\n  list() {\n    const n = unreadMsg();\n    const rows = store.order.map(row).join('');\n    return `<section class=\"dp-scr dp-scr-list\">${hd({ back: topBack(), title: '魂讯', sub: n ? `${n} 条未读` : '都看过了', right: `<button class=\"dp-hb\" data-go=\"newgroup\" aria-label=\"发起群聊\">${ic('plus')}</button>` })}\n      <div class=\"dp-bd\">${rows || '<p class=\"dp-note in\">还没有能聊的人。</p>'}<p class=\"dp-note\">想加新的人？先在正文里和 TA 交换联系方式。</p></div></section>`;\n  },\n  chat(key) {\n    const c = conv(key), p = c.p, para = c.type === 'pdm', s = STATE[p.state] || STATE.ok;\n    c.unread = 0;\n    const sub = para ? '原线 · 那边没有你' : p.state === 'ok' ? `${p.title || '魂师'}${p.lv ? ' · ' + p.lv + '级' : ''} · 在线` : (p.stateText || s.t);\n    const ban = para ? `<div class=\"dp-ban s-para\">${ic('para')}<span>彼端来信。对面是没被你影响过的${esc(p.name)}，只在镜湖里见过你。</span></div>`\n      : BANNER[p.state] ? `<div class=\"dp-ban s-${p.state}\">${ic(s.ic)}<span>${esc(BANNER[p.state](p))}</span></div>` : '';\n    return `<section class=\"dp-scr dp-scr-chat ${para ? 'para' : ''}\" data-key=\"${esc(key)}\">\n      ${hd({ left: av(p, 'sm'), go: para ? '' : 'profile:' + p.id, title: who(p, para), sub: `<span class=\"dp-sub s-${para ? 'ok' : p.state}\">${esc(sub)}</span>`, right: para ? '' : `<button class=\"dp-hb\" data-go=\"profile:${esc(p.id)}\" aria-label=\"名帖\">${ic('more')}</button>` })}\n      ${ban}<div class=\"dp-bd dp-chat\">${msgsHtml(c)}</div>\n      ${composer(key, para ? '写给彼端…' : p.state === 'dead' || p.state === 'gone' ? '写了也没有人看…' : '给' + p.name + '发消息…', !para)}</section>`;\n  },\n  group(key) {\n    const c = conv(key);\n    c.unread = 0;\n    const can = c.members.filter((id) => ['ok', 'busy'].includes(person(id).state)).length;\n    return `<section class=\"dp-scr dp-scr-chat is-group\" data-key=\"${esc(key)}\">\n      ${hd({ left: `<span class=\"dp-gav\">${c.members.slice(0, 4).map((id) => av(id, 'xs')).join('')}</span>`, title: esc(c.name), sub: `${c.members.length + 1} 人 · 此刻 ${can} 人能回话`, right: `<button class=\"dp-hb\" data-act=\"ginfo\" aria-label=\"群资料\">${ic('more')}</button>` })}\n      ${c.notice ? `<div class=\"dp-ban s-note\">${ic('pin')}<span>${esc(c.notice)}</span></div>` : ''}\n      <div class=\"dp-bd dp-chat\">${msgsHtml(c)}</div>\n      ${composer(key, '在群里说点什么…（@名字 点名）', true)}</section>`;\n  },\n  contacts() {\n    const grp = (list) => list.map((p) => `<button class=\"dp-row dp-crow s-${p.state}\" data-go=\"profile:${esc(p.id)}\">${av(p)}\n      <span class=\"dp-row-m\"><b>${esc(p.name)}</b><span class=\"dp-row-p\">${p.state === 'none' ? esc(p.met) : `${esc(p.title || '魂师')}${p.lv ? ' · ' + p.lv + '级' : ''}${p.soul ? ' · ' + esc(p.soul) : ''}`}</span></span>\n      <span class=\"dp-row-r\">${p.state === 'none' ? ic('lock', 'dp-lk') : `<i class=\"dp-aff a-${affStage(p.aff)}\">${affStage(p.aff)}</i>`}${p.state !== 'ok' && p.state !== 'none' ? chip(p) : ''}</span></button>`).join('');\n    const live = D.people.filter((p) => !p.paraOnly);\n    const A = live.filter((p) => !['none', 'dead', 'gone'].includes(p.state)), B = live.filter((p) => p.state === 'none'), C = live.filter((p) => ['dead', 'gone'].includes(p.state));\n    return `<section class=\"dp-scr dp-scr-contacts\">${hd({ back: topBack(), title: '名册', sub: `${A.length} 位已互留 · 取自状态栏的人物` })}\n      <div class=\"dp-bd\"><h4 class=\"dp-sec\"><span>已互留</span><i>${A.length}</i></h4>${grp(A) || '<p class=\"dp-note in\">还没有人。</p>'}\n      <h4 class=\"dp-sec\"><span>还没交换联系方式</span><i>${B.length}</i></h4><p class=\"dp-note in\">这些人你认识，但没有 TA 的联系方式。在正文里当面交换之后，才会出现在上面。</p>${grp(B)}\n      ${C.length ? `<h4 class=\"dp-sec\"><span>联系不上</span><i>${C.length}</i></h4>${grp(C)}` : ''}</div></section>`;\n  },\n  profile(id) {\n    const p = person(id), locked = p.state === 'none', stage = affStage(p.aff), pos = Math.max(0, Math.min(100, (p.aff + 200) / 4));\n    const pinned = conv('dm:' + p.id).pin;\n    return `<section class=\"dp-scr dp-scr-profile s-${p.state}\">${hd({ title: '名帖' })}\n      <div class=\"dp-bd\"><div class=\"dp-pf-top\">${av(p, 'lg')}<h3>${esc(p.name)}</h3><p>${locked ? esc((p.tags || []).join(' · ')) : `${esc(p.title || '魂师')}${p.lv ? ' · ' + p.lv + '级' : ''}${p.soul ? ' · ' + esc(p.soul) : ''}`}</p>${rings(p)}${p.sign ? `<q>${esc(p.sign)}</q>` : ''}</div>\n      <div class=\"dp-pf-box\">${chip(p)}<dl><dt>此刻</dt><dd>${esc(locked ? p.met : p.doing)}</dd><dt>所在</dt><dd>${esc(p.where)}</dd><dt>情绪</dt><dd>${esc(p.mood)}</dd></dl></div>\n      <div class=\"dp-pf-box\"><div class=\"dp-affbar\"><b>好感 ${p.aff > 0 ? '+' : ''}${p.aff}</b><em class=\"a-${stage}\">${stage}</em><div class=\"dp-afft\"><i style=\"left:${pos}%\"></i></div><span>不共戴天</span><span>陌路</span><span>生死之交</span></div>\n        ${p.love != null ? `<div class=\"dp-love\"><b>情意</b><div><i style=\"width:${p.love}%\"></i></div><em>${p.love}</em></div>` : ''}\n        <p class=\"dp-tags\">${(p.tags || []).filter(Boolean).map((t) => `<i>${esc(t)}</i>`).join('')}</p></div>\n      <div class=\"dp-pf-acts\">${locked ? `<p class=\"dp-note in\">${ic('lock')}还没交换联系方式。回到正文，当面找 TA 要。</p><button class=\"dp-btn\" data-act=\"manual:${esc(p.id)}\">${ic('check')}<span>正文里换过了，手动登记</span></button>`\n        : `<button class=\"dp-btn pri\" data-go=\"chat:dm:${esc(p.id)}\">${ic('msg')}<span>发消息</span></button><button class=\"dp-btn\" data-act=\"pickto:${esc(p.id)}\">${ic('group')}<span>拉进群</span></button><button class=\"dp-btn\" data-act=\"pin:${esc(p.id)}\">${ic('pin')}<span>${pinned ? '取消置顶' : '置顶'}</span></button><button class=\"dp-btn\" data-act=\"pchat:${esc(p.id)}\">${ic('para')}<span>写给彼端的 TA</span></button>`}</div>\n      <p class=\"dp-note\">以上读自状态栏变量「人物.${esc(p.real || p.name)}」，手机不会改它。</p></div></section>`;\n  },\n  newgroup() {\n    const list = D.people.filter((p) => !p.paraOnly && !['none', 'dead', 'gone', 'block'].includes(p.state));\n    return `<section class=\"dp-scr dp-scr-newgroup\">${hd({ title: '发起群聊', sub: '只能拉已经互留联系方式的人' })}\n      <div class=\"dp-bd\"><label class=\"dp-field\"><span>群名</span><input type=\"text\" value=\"临时小队\" maxlength=\"14\"></label>\n      ${list.map((p) => `<button class=\"dp-row dp-crow dp-pick ${S.picks.has(p.id) ? 'on' : ''}\" data-act=\"pickm:${esc(p.id)}\">${av(p)}<span class=\"dp-row-m\"><b>${esc(p.name)}</b><span class=\"dp-row-p\">${esc(p.state === 'ok' ? '在线' : p.stateText)}</span></span><span class=\"dp-row-r\"><i class=\"dp-ck\">${ic('check')}</i></span></button>`).join('') || '<p class=\"dp-note in\">还没有能拉进群的人。</p>'}</div>\n      <footer class=\"dp-ft pad\"><button class=\"dp-btn pri wide\" data-act=\"mkgroup\">${ic('group')}<span>建群（已选 <b data-picks>${S.picks.size}</b> 人）</span></button></footer></section>`;\n  },\n  parallel() {\n    const t = S.ptab, P = store.para, dmN = Object.values(P.dms).reduce((n, c) => n + (c.unread || 0), 0);\n    const tabs = [['forum', '镜湖', 0], ['dm', '来信', dmN], ['verdict', '评说', P.fresh]];\n    let body = '';\n    const refresh = `<button class=\"dp-btn\" data-act=\"pararefresh\">${ic('redo')}<span>${S.busy.has('para') ? '镜湖正在起波纹…' : '让镜湖现在更新一次'}</span></button>`;\n    if (t === 'forum') body = P.posts.map((p) => `<button class=\"dp-post ${p.hot ? 'hot' : ''}\" data-go=\"post:post:${esc(p.id)}\"><span class=\"dp-ptag t-${esc(p.tag)}\">${esc(p.tag)}</span><b class=\"dp-pt\">${esc(p.title)}</b><p class=\"dp-px\">${esc(String(p.body || '').split('\\n')[0])}</p>\n        <span class=\"dp-pm\">${av(p.by, 'xs')}<em>${p.by ? who(person(p.by), 1) : esc(p.anon || '匿名')}</em><time>${esc(p.tm)}</time><span>${ic('reply')}${(p.cms || []).length}</span><span>${ic('eye')}${esc(p.views || '')}</span></span></button>`).join('')\n      + `<p class=\"dp-note\">${P.posts.length ? '' : '镜湖还很平静。'}每过 ${S.set.paraEvery} 层正文，镜湖会按你最近做的事更新一次。</p><div class=\"dp-pf-acts\">${refresh}</div>`;\n    if (t === 'dm') body = Object.keys(P.dms).map((id) => { const c = conv('pd:' + id), last = c.msgs.slice(-1)[0];\n      return `<button class=\"dp-row ${c.unread ? 'has-new' : ''}\" data-go=\"pchat:pd:${esc(id)}\">${av(id)}<span class=\"dp-row-m\"><b>${who(person(id), 1)}</b><span class=\"dp-row-p\">${preview(c)}</span></span><span class=\"dp-row-r\"><time>${esc((last && last.tm) || '')}</time>${c.unread ? `<i class=\"dp-badge\">${c.unread}</i>` : ''}</span></button>`; }).join('')\n      + `<p class=\"dp-note\">彼端的人不认识这条线上的你，只在镜湖里见过。去名帖里点“写给彼端的 TA”，就能给原线的人写信。</p>`;\n    if (t === 'verdict') body = P.verdicts.map((v, i) => `<article class=\"dp-vd ${i === 0 && P.fresh ? 'is-new' : ''}\"><header><i>${esc(v.floor)}</i><b>${esc(v.act)}</b></header><ul>${(v.says || []).map((s) => `<li>${av(s.by, 'xs')}<div><em>${s.by ? who(person(s.by), 1) : esc(s.anon || '匿名')}</em><p>${esc(s.x)}</p></div><span class=\"dp-tone t-${esc(s.tone)}\">${esc(s.tone)}</span></li>`).join('')}</ul></article>`).join('')\n      + (P.verdicts.length ? '' : `<p class=\"dp-note\">还没有人评说你。正文里做点什么吧。</p><div class=\"dp-pf-acts\">${refresh}</div>`);\n    if (t === 'verdict' && P.fresh) { P.fresh = 0; save(); }\n    return `<section class=\"dp-scr dp-scr-parallel para\">${hd({ back: topBack(), title: '平行线', sub: '另一端，是没被你影响过的那条时间线' })}\n      <div class=\"dp-seg\" data-on=\"${t}\">${tabs.map(([k, n, b]) => `<button data-act=\"ptab:${k}\" aria-selected=\"${k === t}\">${n}${b ? `<i class=\"dp-badge\">${b}</i>` : ''}</button>`).join('')}</div>\n      <div class=\"dp-bd dp-pb-${t}\">${body}</div></section>`;\n  },\n  post(key) {\n    const p = conv(key);\n    return `<section class=\"dp-scr dp-scr-post para\" data-key=\"${esc(key)}\">${hd({ title: '镜湖', sub: esc(p.tag) + ' · ' + esc(p.tm || '') })}\n      <div class=\"dp-bd\"><article class=\"dp-pfull\"><span class=\"dp-ptag t-${esc(p.tag)}\">${esc(p.tag)}</span><h3>${esc(p.title)}</h3><div class=\"dp-pm\">${av(p.by, 'sm')}<em>${p.by ? who(person(p.by), 1) : esc(p.anon || '匿名')}</em><time>${esc(p.tm || '')}</time></div>${String(p.body || '').split('\\n').map((x) => `<p>${esc(x)}</p>`).join('')}</article>\n      <h4 class=\"dp-sec\"><span>回帖</span><i data-cmn>${p.cms.length}</i></h4><div class=\"dp-cms\">${p.cms.map((c) => cm(c)).join('')}</div></div>\n      ${composer(key, `以“那条线的${D.hero.name}”回帖…`, false)}</section>`;\n  },\n  album() {\n    const pics = [];\n    [...store.order, ...Object.keys(store.para.dms).map((i) => 'pd:' + i)].forEach((k) => conv(k).msgs.forEach((m) => { if (m.k === 'img') pics.push(m); }));\n    return `<section class=\"dp-scr dp-scr-album\">${hd({ back: topBack(), title: '相册', sub: `${pics.length} 张 · 聊天里收发的图都在这` })}\n      <div class=\"dp-bd\"><div class=\"dp-grid\">${pics.reverse().map((m, i) => `<figure class=\"dp-pic\" style=\"--i:${i};${m.src ? `background-image:url('${esc(m.src)}')` : ''}\" ${m.src ? '' : `data-pic=\"${m.pic || picOf(m.x)}\"`}><figcaption>${esc(m.x || '')}</figcaption></figure>`).join('')}</div>\n      <p class=\"dp-note\">${pics.length ? '' : '还没有图。聊天里点＋就能发。'}你发的图压缩后存在这个聊天里；发给角色时，交给模型的是你写的那句画面描述。角色发来的图只有描述，配的是画出来的底图。</p></div></section>`;\n  },\n  settings() {\n    const s = S.set, sw = (k) => `<button class=\"dp-sw ${s[k] ? 'on' : ''}\" data-act=\"sw:${k}\" role=\"switch\" aria-checked=\"${!!s[k]}\"></button>`;\n    const step = (k, lo, hi) => `<span class=\"dp-step\"><button data-act=\"step:${k}:-1:${lo}:${hi}\">−</button><b>${s[k]}</b><button data-act=\"step:${k}:1:${lo}:${hi}\">+</button></span>`;\n    const r = (t, ctl, hint) => `<div class=\"dp-set\"><div><b>${t}</b>${hint ? `<span>${hint}</span>` : ''}</div>${ctl}</div>`;\n    return `<section class=\"dp-scr dp-scr-settings\">${hd({ back: topBack(), title: '设置' })}\n      <div class=\"dp-bd\">\n      <h4 class=\"dp-sec\"><span>外观</span></h4>\n      <div class=\"dp-themes\">${S.themes.map((t) => `<button class=\"dp-tc ${t.id === S.theme ? 'on' : ''}\" data-act=\"theme:${t.id}\" data-t=\"${t.id}\"><i class=\"dp-tc-p\">${(t.sw || []).map((c) => `<u style=\"background:${c}\"></u>`).join('')}</i><b>${t.name}</b><span>${t.hint}</span></button>`).join('')}</div>\n      ${r('动效', `<span class=\"dp-opt\">${[['auto', '跟状态栏'], ['full', '完整'], ['lite', '克制'], ['off', '关']].map(([k, n]) => `<button data-act=\"motion:${k}\" aria-selected=\"${s.motion === k}\">${n}</button>`).join('')}</span>`)}\n      <h4 class=\"dp-sec\"><span>回复用哪个接口</span></h4>\n      <div class=\"dp-radio\"><button data-act=\"api:tavern\" aria-selected=\"${s.api === 'tavern'}\"><i></i><div><b>跟随酒馆</b><span>用酒馆当前连着的接口和模型，不用另外配</span></div></button>\n        <button data-act=\"api:custom\" aria-selected=\"${s.api === 'custom'}\"><i></i><div><b>单独配一个</b><span>OpenAI 兼容接口，手机回复不占正文的额度</span></div></button></div>\n      <div class=\"dp-api\" ${s.api === 'custom' ? '' : 'hidden'}><label class=\"dp-field\"><span>地址</span><input type=\"url\" data-k=\"url\" value=\"${esc(s.url)}\" placeholder=\"https://…/v1\"></label><label class=\"dp-field\"><span>密钥</span><input type=\"password\" data-k=\"key\" value=\"${esc(s.key)}\" placeholder=\"只存在本机浏览器\"></label><label class=\"dp-field\"><span>模型</span><input type=\"text\" data-k=\"model\" list=\"dlph-models\" value=\"${esc(s.model)}\" placeholder=\"点右边拉取列表\"><button class=\"dp-mini\" data-act=\"models\">拉取</button></label><datalist id=\"dlph-models\"></datalist><button class=\"dp-btn\" data-act=\"testapi\">${ic('link')}<span>测试连接</span></button></div>\n      <h4 class=\"dp-sec\"><span>写进正文</span></h4>\n      ${r('把聊天记录告诉正文', sw('inject'), '正文里的角色会记得你们在手机上说过什么')}\n      ${r('写在倒数第几层', step('depth', 0, 8), '离最新一层越近，角色越当回事')}\n      ${r('每段对话带几条', step('per', 2, 20))}\n      <h4 class=\"dp-sec\"><span>回复规则</span></h4>\n      ${r('交战、昏迷、身故时不回', sw('noReply'), '按状态栏的战斗、气血、伤势、人物归档判断')}\n      ${r('好感太低会被拉黑', sw('block'), '跌到「敌意」以下开始有概率；回到「陌路」自动解除')}\n      ${r('群里一次最多几人接话', step('maxGroup', 1, 8))}\n      ${r('镜湖自动更新', sw('paraAuto'), '要多调一次模型')}\n      ${r('镜湖每几层更新一次', step('paraEvery', 1, 20), '平行线的帖子和评说')}\n      <h4 class=\"dp-sec\"><span>主动消息</span></h4>\n      ${r('别人会主动找你', sw('proactive'), '正文推进几层后，有人主动发私聊、在群里开话头；要多调一次模型')}\n      ${r('最少隔几层来一次', step('proEvery', 2, 20))}\n      ${r('原线的人也会来信', sw('paraPro'), '平行线那头没被你影响过的人')}\n      <div class=\"dp-pf-acts\"><button class=\"dp-btn\" data-act=\"protest\">${ic('msg')}<span>${S.busy.has('pro') ? '正在看谁会来找你…' : '现在就看看谁会来找你'}</span></button></div>\n      ${r('新消息横幅', sw('notify'))}\n      <h4 class=\"dp-sec\"><span>数据</span></h4>\n      <div class=\"dp-pf-acts\"><button class=\"dp-btn\" data-act=\"export\">${ic('album')}<span>导出聊天记录</span></button><button class=\"dp-btn bad\" data-act=\"wipe\">${ic('trash')}<span>清空本聊天的手机数据</span></button></div>\n      <p class=\"dp-note\">聊天记录跟着酒馆的这一个聊天走，换聊天就是另一部手机。斗罗小手机 ${VERSION}</p></div></section>`;\n  },\n  empty() { return `<section class=\"dp-scr dp-scr-empty\"><div class=\"dp-empty\"><i class=\"dp-emb\"></i><b>选一段对话</b><span>左边点开谁，就在这里聊</span></div></section>`; },\n  home() {\n    let html = S.opts.home ? S.opts.home(ctx()) : '';\n    if (html) {\n      const tiles = [];\n      if (hasGfChat()) {\n        tiles.push(`<button class=\"hm-app dp-gc-home-app\" style=\"--i:9\" data-go=\"gfchat\"><span class=\"hm-ico\" style=\"--i:6\">${ic('gfchat')}</span><i class=\"dp-badge\" data-badge=\"gfchat\" hidden></i><em>聊天群</em></button>`);\n      }\n      extPhoneApps().forEach((app, i) => {\n        tiles.push(`<button class=\"hm-app dp-ext-home-app\" style=\"--i:${10 + i}\" data-go=\"ext:${esc(app.id)}\"><span class=\"hm-ico\" style=\"--i:${(i % 6) + 1}\">${extAppIcon(app)}</span><i class=\"dp-badge\" data-badge=\"ext:${esc(app.id)}\" hidden></i><em>${esc(app.name)}</em></button>`);\n      });\n      if (tiles.length) {\n        html = html.replace('<div class=\"hm-apps\">', '<div class=\"hm-apps has-gc\">');\n        const idx = html.lastIndexOf('</div></div>');\n        if (idx >= 0) html = html.slice(0, idx) + tiles.join('') + html.slice(idx);\n      }\n    }\n    return `<section class=\"dp-scr dp-scr-home\">${html}</section>`;\n  },\n  gfchat() { return renderGfChat(); },\n};\nSCR.pchat = SCR.chat;\n\n/* ───────── 跨时代聊天群 App（D10：仅在 金手指.类型 === \"跨时代聊天群\" 时出现） ───────── */\nconst GC_SEAL = {\n  武魂殿: { c1: '#F2CE6B', c2: '#2a1838', svg: '<path d=\"M0-13v26M-5-7h10\" stroke-width=\"2\"/><path d=\"M-3-4C-10-8-14-4-15 2c4-2 7-2 9 0M3-4C10-8 14-4 15 2c-4-2-7-2-9 0\" stroke-width=\"1.3\"/>' },\n  史莱克: { c1: '#7CF5C8', c2: '#0c2a22', svg: Array.from({ length: 7 }, (_, i) => { const a = (i / 7) * Math.PI * 2 - Math.PI / 2; return `<circle cx=\"${(Math.cos(a) * 9).toFixed(1)}\" cy=\"${(Math.sin(a) * 9).toFixed(1)}\" r=\"2.2\" fill=\"currentColor\" stroke=\"none\"/>`; }).join('') + '<circle r=\"4\" stroke-width=\"1.4\"/>' },\n  唐门: { c1: '#9FB4FF', c2: '#141a33', svg: '<path d=\"M0-13L3-3 13 0 3 3 0 13-3 3-13 0-3-3Z\" stroke-width=\"1.3\"/><circle r=\"2.2\" fill=\"currentColor\" stroke=\"none\"/>' },\n  天斗皇室: { c1: '#E8C670', c2: '#241c0d', svg: '<path d=\"M-11 8L-13-5-5 1 0-10 5 1 13-5 11 8Z\" stroke-width=\"1.4\"/><path d=\"M-11 11h22\" stroke-width=\"1.4\"/>' },\n  星罗皇室: { c1: '#D8B4E2', c2: '#201228', svg: '<polygon points=\"0,-13 4,-4 13,-4 6,2 9,12 0,6 -9,12 -6,2 -13,-4 -4,-4\" stroke-width=\"1.3\"/>' },\n  传灵塔: { c1: '#6FE8F5', c2: '#0b242c', svg: '<path d=\"M0-13L8-3H-8Z M-10 3H10 M-7 3L-9 11H9L7 3\" stroke-width=\"1.4\"/>' },\n  本体宗: { c1: '#F0A868', c2: '#29170b', svg: '<polygon points=\"0,-13 11,-6 11,6 0,13 -11,6 -11,-6\" stroke-width=\"1.5\"/><circle r=\"4\" stroke-width=\"1.4\"/>' },\n  圣灵教: { c1: '#C98AE8', c2: '#1f0e29', svg: '<path d=\"M6-11A12 12 0 1 0 6 11A9 9 0 1 1 6-11Z\" stroke-width=\"1.4\"/><circle cx=\"-4\" cy=\"0\" r=\"2\" fill=\"currentColor\" stroke=\"none\"/>' },\n  神界: { c1: '#F5DF8E', c2: '#1e1a0c', svg: '<circle r=\"6\" stroke-width=\"1.4\"/><path d=\"M0-14v4M0 10v4M-14 0h4M10 0h4M-10-10l3 3M7 7l3 3M10-10l-3 3M-7 7l-3 3\" stroke-width=\"1.3\"/>' },\n  散修: { c1: '#C8C2B0', c2: '#1d1c19', svg: '<path d=\"M-11 4a5 5 0 0 1 1-10 6 6 0 0 1 11-1 4 4 0 0 1 1 8H-11Z\" stroke-width=\"1.4\"/>' },\n};\nconst GC_ERA_TX = { 斗1: '羊皮纸', 斗2: '魂导', 神界: '神界', 英雄: '神界', 斗3: '全息', 斗4: '星舰' };\nconst GC_TN = { 白: '白阶', 黄: '黄阶', 紫: '紫阶', 红: '红阶', 金: '金阶', 彩: '彩阶' };\nconst hasGfChat = () => Boolean(stat && stat.金手指 && stat.金手指.类型 === '跨时代聊天群' && stat.金手指.聊天群);\nconst unreadGfChat = () => (hasGfChat() && store && store.gfChat ? Number(store.gfChat.unread) || 0 : 0);\nconst gcYear = (d) => Number((/斗罗历(-?\\d+)年/u.exec(String(d || '')) || [])[1]) || 0;\nfunction gcAvatar(name, era) {\n  const lib = W.DLAvatars;\n  let src = null;\n  if (lib && typeof lib.pick === 'function' && name) {\n    try { const hit = lib.pick(name, { part: era }); if (hit && hit.src) src = hit.src; } catch (_) { /* 退回首字 */ }\n  }\n  if (src) return `<span class=\"dp-gc-av img\" data-era=\"${esc(era || '')}\"><img src=\"${esc(src)}\" alt=\"${esc(name)}\"></span>`;\n  return `<span class=\"dp-gc-av\" data-era=\"${esc(era || '')}\">${esc(first(name))}</span>`;\n}\nfunction gcFormatText(t) {\n  return esc(t).replace(/@([^\\s@]{1,12})/gu, '<span class=\"at\">@$1</span>');\n}\nfunction syncGfChatEntry() {\n  if (!phone) return;\n  const on = hasGfChat();\n  $$('[data-tab=\"gfchat\"]', phone).forEach((b) => { b.hidden = !on; });\n}\nfunction renderGfChat() {\n  if (!hasGfChat()) {\n    return `<section class=\"dp-scr dp-scr-gfchat\"><div class=\"dp-empty\"><i class=\"dp-emb\"></i><b>未启用跨时代聊天群</b><span>只有在开局选择了「跨时代聊天群」的聊天里才可用</span></div></section>`;\n  }\n  const G = stat.金手指, C = G.聊天群;\n  const gc = (store && store.gfChat) || { msgs: [], packets: [], unread: 0 };\n  const friends = Array.isArray(C.群友) ? C.群友 : [];\n  const spoilers = Array.isArray(C.剧透) ? C.剧透 : [];\n  const msgs = Array.isArray(gc.msgs) ? gc.msgs : [];\n  const pkMap = new Map((Array.isArray(gc.packets) ? gc.packets : []).map((p) => [p.id, p]));\n  const baseEras = ['斗1', '斗2', '斗3', '斗4'];\n  const extraEras = ['神界', '英雄'].filter((e) => friends.some((f) => f.部 === e) || D.world.part === e);\n  const showEras = [...baseEras.slice(0, 2), ...extraEras, ...baseEras.slice(2)];\n  const eraCount = new Set(friends.map((f) => f.部).concat(D.world.part ? [D.world.part] : [])).size;\n  const meY = gcYear(D.world.date);\n  const busy = S.busy.has('gfchat');\n  const tick = [20, 40, 60, 80];\n  const modalPk = S.gc.modalPk ? pkMap.get(S.gc.modalPk) : null;\n\n  const eraBar = showEras.map((era) => {\n    const fs = friends.filter((f) => f.部 === era);\n    const hasMe = D.world.part === era;\n    const empty = !fs.length && !hasMe;\n    return `<div class=\"dp-gc-eras${empty ? ' empty' : ''}\" data-era=\"${esc(era)}\">\n      <span class=\"k\">${esc(era)}<small>${esc(GC_ERA_TX[era] || '')}</small></span>\n      <span class=\"avs\">${hasMe ? '<i class=\"you\" title=\"你\">你</i>' : ''}${fs.map((f) => `<i title=\"${esc(f.姓名)}\">${esc(first(f.姓名))}</i>`).join('')}</span>\n    </div>`;\n  }).join('');\n\n  const msgHtml = msgs.length ? msgs.map((m) => {\n    if (m.kind === 'bot') {\n      return `<div class=\"dp-gc-bot\"><i>群</i><div><b>${esc(m.who || (G.口吻 && G.口吻.名字) || '群主机器人')}</b>${esc(m.text)}</div></div>`;\n    }\n    if (m.kind === 'shift') {\n      return `<div class=\"dp-gc-shift\"><h6 data-t=\"世界线偏移\">世界线偏移</h6><p><b>${esc(m.who)}</b>：${esc(m.text)}</p></div>`;\n    }\n    if (m.kind === 'me') {\n      const spHit = m.spoiler ? spoilers.find((s) => s.内容 && m.text.includes(s.内容.slice(0, 8))) : null;\n      const spSt = (spHit && spHit.状态) || m.spoilerState;\n      return `<div class=\"dp-gc-m me\"><div class=\"dp-gc-bw\">\n        <div class=\"dp-gc-who\"><time>${esc(m.tm || '')}</time><i>群名片</i><b>${esc(m.who || C.群名片 || '我')}</b></div>\n        <div class=\"dp-gc-bx\"><div class=\"dp-gc-b\">${gcFormatText(m.text)}</div>${spSt ? `<span class=\"dp-gc-sp\" data-s=\"${esc(spSt)}\">${esc(spSt)}</span>` : ''}</div>\n      </div></div>`;\n    }\n    const era = m.era || ((friends.find((f) => f.姓名 === m.who) || {}).部) || '';\n    const pk = m.packetId ? pkMap.get(m.packetId) : null;\n    const seal = pk ? (GC_SEAL[pk.封] || GC_SEAL.散修) : null;\n    return `<div class=\"dp-gc-m\" data-era=\"${esc(era)}\">\n      ${gcAvatar(m.who, era)}\n      <div class=\"dp-gc-bw\">\n        <div class=\"dp-gc-who\"><b>${esc(m.who)}</b>${era ? `<i>${esc(era)}</i>` : ''}<time>${esc(m.tm || '')}</time></div>\n        <div class=\"dp-gc-b\" ${era === '斗4' ? `data-log=\"LOG · ${esc(m.tm || '00:00')}\"` : ''}>${gcFormatText(m.text)}</div>\n        ${pk ? `<button type=\"button\" class=\"dp-gc-pk${pk.已领 ? ' open' : ''}\" data-act=\"gcpk:${esc(pk.id)}\" data-tier=\"${esc(pk.品阶 || '黄')}\" style=\"--e1:${seal.c1};--e2:${seal.c2}\">\n          <span class=\"dp-gc-pk-seal\"><svg viewBox=\"-16 -16 32 32\" fill=\"none\" stroke=\"currentColor\">${seal.svg}</svg></span>\n          <span class=\"dp-gc-pk-t\"><b>${esc(pk.祝福 || pk.名称)}</b>${pk.已领 ? `<em>已领取 · ${esc(pk.名称)}</em>` : `<small>${esc(pk.封 || '斗罗')}封口 · 点开领取</small>`}</span>\n        </button>` : ''}\n      </div>\n    </div>`;\n  }).join('') : '<div class=\"dp-gc-bot\"><i>群</i><div><b>群主机器人</b>群里静悄悄的，发句话或者点「动一动」听听跨时代的回音吧。</div></div>';\n\n  const drFriends = friends.map((f) => {\n    const moved = f.世界线 && f.世界线 !== '照原作走。' && f.世界线 !== '照原作走';\n    const fy = gcYear(f.时间点);\n    const gap = meY && fy ? (fy === meY ? '同年代' : fy > meY ? `晚你 ${fy - meY} 年` : `早你 ${meY - fy} 年`) : f.时间点;\n    return `<article class=\"dp-gc-fr\" data-era=\"${esc(f.部)}\"${moved ? ' data-moved=\"1\"' : ''}>\n      ${gcAvatar(f.姓名, f.部)}\n      <header><b>${esc(f.姓名)}</b><span>${esc(f.部)}</span></header>\n      <div class=\"gap\">${esc(gap)}</div>\n      <p>${esc(f.处境)}</p>\n      <p class=\"wl\"><span>${moved ? '世界线已偏移' : '世界线'}</span>${esc(f.世界线)}</p>\n    </article>`;\n  }).join('');\n\n  const modalSeal = modalPk ? (GC_SEAL[modalPk.封] || GC_SEAL.散修) : null;\n  const modalHtml = modalPk ? `<div class=\"dp-gc-open on done\" style=\"--e1:${modalSeal.c1};--e2:${modalSeal.c2}\" data-tier=\"${esc(modalPk.品阶 || '黄')}\">\n    <div class=\"dp-gc-env\">\n      <div class=\"dp-gc-env-back\"></div>\n      <div class=\"dp-gc-env-card\" data-tier=\"${esc(modalPk.品阶 || '黄')}\">\n        <span class=\"t\">${esc(GC_TN[modalPk.品阶] || modalPk.品阶 || '黄阶')}</span>\n        <b>${esc(modalPk.名称)}</b>\n        <span class=\"src\">${esc(modalPk.出处 || '斗罗')} · 落点：${esc(modalPk.落点 || '行囊')}</span>\n        <p>${esc(modalPk.说明)}</p>\n        <span class=\"from\">来自 ${esc(modalPk.群友)}（${esc(modalPk.封 || '散修')}）</span>\n      </div>\n      <div class=\"dp-gc-env-front\"></div>\n      <div class=\"dp-gc-env-flap\"></div>\n    </div>\n    <div class=\"dp-gc-open-act\">\n      <button type=\"button\" data-act=\"gcclaim:${esc(modalPk.id)}\" ${modalPk.已领 ? 'disabled' : ''}>${modalPk.已领 ? '已收进待入账' : '收下（进待入账）'}</button>\n      <button type=\"button\" class=\"sec\" data-act=\"gcclosepk\">先放着</button>\n      <small>领完进状态栏「待入账」，下一轮正文由 AI 落地结算</small>\n    </div>\n  </div>` : '';\n\n  return `<section class=\"dp-scr dp-scr-gfchat\" data-name=\"gfchat\">\n    <div class=\"dp-gc\">\n      <header class=\"dp-gc-hd\">\n        <button type=\"button\" class=\"dp-gc-ib\" data-act=\"back\" aria-label=\"返回\">${ic('back')}</button>\n        <div class=\"dp-gc-tt\"><b>${esc(C.群名)}</b><span>${friends.length} 位群友 · 横跨 ${eraCount} 个时代</span></div>\n        <div class=\"dp-gc-hr\">\n          <button type=\"button\" class=\"dp-gc-pr\" data-act=\"gcdr\" title=\"威望与群友\"><b>${C.威望}</b><span>${esc(C.威望档)}</span><i style=\"--p:${C.威望}%\"></i></button>\n          <button type=\"button\" class=\"dp-gc-ib\" data-act=\"gcdr\" aria-label=\"群友与剧透\">${ic('group')}</button>\n        </div>\n      </header>\n      <div class=\"dp-gc-era\">${eraBar}</div>\n      <div class=\"dp-gc-log\">\n        ${msgHtml}\n        ${busy ? '<div class=\"dp-gc-typing on\"><span class=\"dots\"><i></i><i></i><i></i></span><span>跨时代回音传入中…</span></div>' : ''}\n      </div>\n      <div class=\"dp-gc-ft${S.gc.spoiler ? ' sp' : ''}\">\n        <div class=\"dp-gc-atp\" ${S.gc.atOpen ? '' : 'hidden'}>${friends.map((f) => `<button type=\"button\" data-act=\"gcpick:${esc(f.姓名)}\">${gcAvatar(f.姓名, f.部)}<span>${esc(f.姓名)}</span></button>`).join('')}</div>\n        <div class=\"dp-gc-as\">以 <b>${esc(C.群名片 || '神秘群友')}</b> 发言<span>${C.人设 ? '· ' + esc(C.人设) : ''}</span></div>\n        <div class=\"dp-gc-tools\">\n          <button type=\"button\" class=\"dp-gc-chip\" data-act=\"gcsp\" aria-pressed=\"${S.gc.spoiler}\">剧透</button>\n          <button type=\"button\" class=\"dp-gc-chip\" data-act=\"gcat\">@ 群友</button>\n          <button type=\"button\" class=\"dp-gc-chip\" data-act=\"gcidle\" ${busy ? 'disabled' : ''}>动一动</button>\n          <small>${S.gc.spoiler ? '本句将记入剧透账（待应验）' : '切中改命点涨威望，落空掉威望'}</small>\n        </div>\n        <form class=\"dp-gc-cmp\">\n          <textarea rows=\"1\" maxlength=\"200\" placeholder=\"${S.gc.spoiler ? '写一句点破未来因果的剧透…' : '给群里发一句话…'}\" ${busy ? 'disabled' : ''}></textarea>\n          <button type=\"submit\" class=\"dp-gc-send\" aria-label=\"发送\" ${busy ? 'disabled' : ''}>${ic('send')}</button>\n        </form>\n      </div>\n      <div class=\"dp-gc-dr${S.gc.drawer ? ' on' : ''}\">\n        <div class=\"dp-gc-dr-bg\" data-act=\"gcdr\"></div>\n        <div class=\"dp-gc-dr-p\">\n          <button type=\"button\" class=\"dp-gc-ib dp-gc-dr-x\" data-act=\"gcdr\" aria-label=\"关闭\">${ic('x')}</button>\n          <h5>威望</h5>\n          <div class=\"dp-gc-prb\"><div class=\"n\"><b>${C.威望}</b><span>${esc(C.威望档)}</span></div><div class=\"bar\"><i style=\"--p:${C.威望}%\"></i>${tick.map((t) => `<s style=\"left:${t}%\"></s>`).join('')}</div><p>剧透应验涨威望、落空掉威望（每次 ±15）。</p></div>\n          <h5>群友<em>${friends.length}/8</em></h5>\n          ${drFriends}\n          <h5>剧透账<em>${spoilers.length}/12</em></h5>\n          ${spoilers.length ? `<ol class=\"dp-gc-spl\">${spoilers.map((s) => `<li data-s=\"${esc(s.状态)}\"><b>${esc(s.群友)}</b><p>${esc(s.内容)}</p><span>${esc(s.状态)}</span></li>`).join('')}</ol>` : '<p class=\"dp-note\" style=\"margin:6px 0\">还没剧透过。</p>'}\n        </div>\n      </div>\n      ${modalHtml}\n    </div>\n  </section>`;\n}\nasync function gcSend(text, idle = false) {\n  if (S.busy.has('gfchat')) return;\n  const api = W.__DL_GF_跨时代聊天群__;\n  if (!api || typeof api.act !== 'function') {\n    toast({ t: '跨时代聊天群', x: '找不到「斗罗金手指·跨时代聊天群」脚本，请确认已启用。' });\n    return;\n  }\n  S.busy.add('gfchat');\n  S.gc.atOpen = false;\n  refreshGfChat();\n  try {\n    const res = idle\n      ? await api.act('活跃', {})\n      : await api.act('发言', { 文本: text, 剧透: S.gc.spoiler });\n    if (!res || !res.ok) {\n      toast({ t: '跨时代聊天群', x: (res && res.why) || '发言失败，请重试' });\n      return;\n    }\n    if (!idle) S.gc.spoiler = false;\n    if (res.stat) stat = clone(res.stat);\n    if (res.威望变化) toast({ t: '威望变动', x: `${res.威望变化 > 0 ? '+' : ''}${res.威望变化} → ${res.威望}（${res.威望档}）` });\n  } catch (e) {\n    toast({ t: '跨时代聊天群', x: '出错：' + errText(e) });\n  } finally {\n    S.busy.delete('gfchat');\n    refreshGfChat(true);\n  }\n}\nasync function gcClaimPacket(id) {\n  const api = W.__DL_GF_跨时代聊天群__;\n  if (!api || typeof api.act !== 'function') {\n    toast({ t: '领红包', x: '找不到「斗罗金手指·跨时代聊天群」脚本' });\n    return;\n  }\n  try {\n    const res = await api.act('领红包', { id });\n    if (!res || !res.ok) {\n      toast({ t: '领红包', x: (res && res.why) || '领取失败' });\n      return;\n    }\n    S.gc.modalPk = null;\n    if (res.stat) stat = clone(res.stat);\n    toast({ t: '已收进待入账', x: `${res.奖励.名称}（${res.奖励.落点}），下轮正文结算` });\n    refreshGfChat();\n  } catch (e) {\n    toast({ t: '领红包', x: '领取失败：' + errText(e) });\n  }\n}\nfunction refreshGfChat(scrollBottom = false) {\n  if (!phone) { badges(); return; }\n  navs().forEach((n) => {\n    if (n.cur && (n.cur.name === 'gfchat' || n.cur.name === 'home')) {\n      n.refresh();\n      if (scrollBottom && n.cur.name === 'gfchat') {\n        const log = $('.dp-gc-log', n.cur.el);\n        if (log) { log.scrollTop = log.scrollHeight; requestAnimationFrame(() => { log.scrollTop = log.scrollHeight; }); }\n      }\n    }\n  });\n  badges();\n}\nconst gfChatBridge = {\n  get() {\n    if (!store) return { msgs: [], packets: [], unread: 0, seeded: false };\n    if (!store.gfChat) store.gfChat = { msgs: [], packets: [], unread: 0, seeded: false };\n    return store.gfChat;\n  },\n  isVisible() {\n    return Boolean(S.open && phone && navs().some((n) => n.cur && n.cur.name === 'gfchat' && n.cur.el && n.cur.el.isConnected));\n  },\n  sync(fn) {\n    if (!store) return;\n    if (!store.gfChat) store.gfChat = { msgs: [], packets: [], unread: 0, seeded: false };\n    try { fn(store.gfChat); } catch (e) { console.warn('[斗罗小手机] 同步聊天群失败', e); }\n    save();\n    refreshGfChat();\n    try { W.dispatchEvent(new W.Event('dl-gfchat-changed')); } catch (_) { /* ignore */ }\n  },\n};\n\n/* ───────── 屏幕栈（与样稿一致） ───────── */\nclass Nav {\n  constructor(box) { this.box = box; this.stack = []; }\n  get cur() { return this.stack[this.stack.length - 1]; }\n  _mk(name, arg) {\n    if (String(name || '').startsWith('ext:')) {\n      const appId = String(name).slice(4);\n      const app = extAppOf(appId);\n      const e = el(`<section class=\"dp-scr dp-scr-ext\" data-name=\"${esc(name)}\" data-ext-app=\"${esc(appId)}\">${hd({ back: topBack(), title: esc(app ? app.name : appId) })}<div class=\"dp-bd dp-ext-host\"></div></section>`);\n      e.dataset.name = name;\n      if (app) {\n        try {\n          const hostEl = $('.dp-ext-host', e);\n          const res = app.render({ stat, host: hostEl, open, close, go, back, toast, esc });\n          if (typeof res === 'string' && hostEl && !hostEl.childNodes.length) hostEl.innerHTML = res;\n          else if (res && res.nodeType && hostEl && !hostEl.childNodes.length) hostEl.appendChild(res);\n        } catch (err) { console.error('[斗罗小手机] 扩展应用渲染失败', appId, err); }\n      }\n      return e;\n    }\n    let html; try { html = SCR[name](arg); } catch (e) { console.error('[斗罗小手机] 画屏失败', name, e); html = SCR.empty(); } const e = el(html); e.dataset.name = name; return e;\n  }\n  _swap(old, neu, anim, origin) {\n    const dur = motion() === 'off' || S.noAnim ? 0 : 460;\n    if (origin && origin.getBoundingClientRect) { const b = this.box.getBoundingClientRect(), r = origin.getBoundingClientRect(); neu.style.setProperty('--ox', (r.left + r.width / 2 - b.left) + 'px'); neu.style.setProperty('--oy', (r.top + r.height / 2 - b.top) + 'px'); }\n    this.box.appendChild(neu);\n    if (dur && anim) { neu.classList.add('in-' + anim); later(dur + 40, () => neu.classList.remove('in-' + anim)); }\n    if (old) { if (dur && anim) { old.classList.add('out-' + anim); old.style.pointerEvents = 'none'; later(dur, () => old.remove()); } else old.remove(); }\n    mounted(neu); changed();\n  }\n  go(name, arg, o = {}) { const old = this.cur, e = this._mk(name, arg); this.stack.push({ name, arg, el: e }); this._swap(old && old.el, e, o.anim || 'fwd', o.origin); }\n  back(anim = 'back') { if (this.stack.length < 2) return false; const top = this.stack.pop(), prev = this.cur; prev.el = this._mk(prev.name, prev.arg); this._swap(top.el, prev.el, anim); return true; }\n  reset(name, arg, anim = 'tab') { const old = this.cur, e = this._mk(name, arg); $$('.dp-scr', this.box).forEach((x) => { if (!old || x !== old.el) x.remove(); }); this.stack = [{ name, arg, el: e }]; this._swap(old && old.el, e, anim); }\n  refresh() { const c = this.cur; if (!c) return; const bd = $('.dp-bd', c.el) || $('.dp-gc-log', c.el), y = bd ? bd.scrollTop : 0; const keep = $('.dp-cmp textarea', c.el) || $('.dp-gc-cmp textarea', c.el); const draft = keep ? keep.value : ''; const e = this._mk(c.name, c.arg); c.el.replaceWith(e); c.el = e; const b2 = $('.dp-bd', e) || $('.dp-gc-log', e); if (b2) b2.scrollTop = y; const ta = $('.dp-cmp textarea', e) || $('.dp-gc-cmp textarea', e); if (ta && draft) { ta.value = draft; if (ta.form && ta.form.classList.contains('dp-cmp')) ta.form.classList.add('has'); } mounted(e, true); }\n}\nfunction mounted(e, keep) {\n  const chat = $('.dp-chat', e) || $('.dp-gc-log', e);\n  if (chat && !keep) { chat.scrollTop = chat.scrollHeight; requestAnimationFrame(() => { chat.scrollTop = chat.scrollHeight; }); }\n  if (e && e.dataset.name === 'gfchat' && S.open && store && store.gfChat && store.gfChat.unread) {\n    store.gfChat.unread = 0;\n    save();\n    badges();\n    try { W.dispatchEvent(new W.Event('dl-gfchat-changed')); } catch (_) { /* ignore */ }\n  }\n}\nconst navs = () => [navA, navB].filter(Boolean);\nfunction changed() {\n  if (!phone) return;\n  const a = navA.cur, b = navB && navB.cur;\n  phone.dataset.scr = a ? a.name : '';\n  phone.dataset.deep = navA.stack.length > 1 ? 1 : 0;\n  const detailOn = navB ? phone.dataset.detail === '1' : false;\n  phone.dataset.para = (a && PARA.includes(a.name)) || (b && detailOn && PARA.includes(b.name)) ? 1 : 0;\n  $$('[data-tab]', phone).forEach((t) => t.setAttribute('aria-selected', a && t.dataset.tab === a.name));\n  badges();\n}\nfunction badges() {\n  const m = unreadMsg(), p = unreadPara(), g = unreadGfChat();\n  const extCounts = new Map();\n  let extSum = 0;\n  for (const app of extPhoneApps()) {\n    let n = 0;\n    try { n = typeof app.badge === 'function' ? (Number(app.badge(stat)) || 0) : 0; } catch (_) { n = 0; }\n    if (n > 0) { extCounts.set('ext:' + app.id, n); extSum += n; }\n  }\n  if (phone) {\n    $$('[data-badge]', phone).forEach((b) => {\n      const k = b.dataset.badge;\n      const n = k === 'msg' ? m : k === 'gfchat' ? g : k && k.startsWith('ext:') ? (extCounts.get(k) || 0) : p;\n      b.textContent = n || ''; b.hidden = !n;\n    });\n    $$('[data-sb=\"unread\"]', phone).forEach((b) => { b.textContent = m; });\n  }\n  const fb = wrap && $('.ph-fab > i', wrap);\n  const tot = m + p + g + extSum;\n  if (fb) { fb.textContent = tot || ''; fb.hidden = !tot; }\n}\nfunction visible(key) {\n  if (!S.open || !phone) return false;\n  return navs().some((n) => { const c = n.cur; if (!c || !c.el.isConnected || c.el.dataset.key !== key) return false; return n === navA || !navB || phone.dataset.fold === '1' || phone.dataset.detail === '1'; });\n}\nfunction refreshTops() { if (!phone) { badges(); return; } navs().forEach((n) => { if (n.cur && (['list', 'contacts', 'parallel', 'home', 'album'].includes(n.cur.name) || String(n.cur.name || '').startsWith('ext:'))) n.refresh(); }); badges(); }\nfunction refreshAll() { if (!phone) return; navs().forEach((n) => n.refresh()); paintSb(); badges(); }\n\nfunction go(name, arg, from) {\n  if (!phone) return;\n  const sh = S.shell;\n  if (sh === 'home') {\n    if (name === 'home') { if (navA.cur.name !== 'home') navA.reset('home', null, 'home'); }\n    else if (isTopScr(name) && navA.cur.name === 'home') navA.go(name, arg, { anim: 'app', origin: from });\n    else if (isTopScr(name)) navA.reset(name, arg, 'tab');\n    else navA.go(name, arg);\n  } else if (sh === 'tabs') {\n    if (isTopScr(name)) navA.reset(name === 'home' ? 'list' : name, arg, 'tab'); else navA.go(name, arg);\n  } else {\n    if (isTopScr(name)) { if (phone.dataset.fold !== '1') phone.dataset.detail = 0; navA.reset(name === 'home' ? 'list' : name, arg, 'tab'); }\n    else {\n      const inB = from && from.closest && from.closest('.dp-pane.b');\n      if (inB) navB.go(name, arg); else navB.reset(name, arg, 'fwd');\n      phone.dataset.detail = 1; changed();\n    }\n  }\n}\nfunction back() {\n  if (!phone) return;\n  if (S.shell === 'home') { if (!navA.back()) { if (navA.cur.name !== 'home') go('home'); else close(); } }\n  else if (S.shell === 'tabs') { if (!navA.back()) close(); }\n  else if (!navB.back()) { if (phone.dataset.detail === '1') { phone.dataset.detail = 0; changed(); if (phone.dataset.fold === '1') navB.reset('empty', null, 'tab'); } else close(); }\n}\n\n/* ───────── 消息进出 ───────── */\nfunction stampMsg(m) { m.id = m.id || newId(); m.tm = m.tm || now(); if (!m.date) m.date = D.world.date; if (m.floor == null) m.floor = floorNow; return m; }\nfunction bump(key) {\n  const k = store.order.indexOf(key);\n  if (k < 0 && (key.startsWith('dm:') || key.startsWith('g:'))) store.order.unshift(key);\n  else if (k > 0) { store.order.splice(k, 1); const c = conv(key); const firstUnpinned = store.order.findIndex((x) => !conv(x).pin); store.order.splice(c.pin ? 0 : Math.max(0, firstUnpinned), 0, key); }\n}\nfunction push(key, m, quiet) {\n  const c = conv(key);\n  stampMsg(m);\n  c.msgs.push(m);\n  bump(key);\n  if (phone) $$(`.dp-scr[data-key=\"${CSS.escape(key)}\"]`, phone).forEach((scr) => {\n    if (c.type === 'post') { const box = $('.dp-cms', scr); box.insertAdjacentHTML('beforeend', cm(m, true)); $('[data-cmn]', scr).textContent = c.msgs.length; const bd = $('.dp-bd', scr); bd.scrollTo({ top: bd.scrollHeight, behavior: 'smooth' }); }\n    else { const box = $('.dp-chat', scr), tp = $('.dp-typing', box); const node = el(bubble(m, c, true)); if (tp) box.insertBefore(node, tp); else box.appendChild(node); box.scrollTo({ top: box.scrollHeight, behavior: motion() === 'off' ? 'auto' : 'smooth' }); }\n  });\n  const shown = visible(key);\n  const mine = m.f === 'me' || m.by === 'me';\n  if (!mine && m.f !== 'sys' && !shown && c.type !== 'post') {\n    c.unread = (c.unread || 0) + 1;\n    const p = person(m.f);\n    if (!quiet && S.set.notify) toast({ av: av(p, 'sm'), t: (c.type === 'group' ? c.name + ' · ' : '') + p.name + (c.type === 'pdm' ? '（原线）' : ''), x: m.k === 'img' ? '[图片] ' + (m.x || '') : m.x, go: [c.type === 'group' ? 'group' : c.type === 'pdm' ? 'pchat' : 'chat', key] });\n  }\n  refreshTops();\n  save();\n  return m;\n}\nfunction redraw(m) { if (phone) $$(`[data-mid=\"${m.id}\"]`, phone).forEach((n) => { const c = convOf(n); n.outerHTML = bubble(m, c); }); }\nfunction setSt(m, st) { if (m.f !== 'me') return; m.st = st; redraw(m); save(); } // 已撤回的不再改状态\nconst convOf = (node) => conv(node.closest('.dp-scr').dataset.key);\nfunction typing(key, pid, on) {\n  if (!phone) return;\n  $$(`.dp-scr[data-key=\"${CSS.escape(key)}\"] .dp-chat`, phone).forEach((box) => {\n    $$(`.dp-typing[data-pid=\"${CSS.escape(pid)}\"]`, box).forEach((n) => n.remove());\n    if (on) { box.appendChild(el(`<div class=\"dp-msg them dp-typing\" data-pid=\"${esc(pid)}\">${av(pid, 'sm')}<div class=\"dp-bw\"><div class=\"dp-bub\"><span class=\"dp-dots\"><i></i><i></i><i></i></span><i class=\"dp-bub-o\"></i></div></div></div>`)); box.scrollTo({ top: box.scrollHeight, behavior: 'smooth' }); }\n  });\n  $$(`.dp-scr[data-key=\"${CSS.escape(key)}\"] .dp-sub`, phone).forEach((s) => { if (on) { s.dataset.keep = s.dataset.keep || s.textContent; s.textContent = '正在输入…'; s.classList.add('typing'); } else if (s.dataset.keep) { s.textContent = s.dataset.keep; delete s.dataset.keep; s.classList.remove('typing'); } });\n}\nfunction sys(key, text) { const c = conv(key), last = c.msgs[c.msgs.length - 1]; if (last && last.f === 'sys' && last.x === text) return; push(key, { f: 'sys', x: text }); }\nfunction sysQuiet(key, text) { const c = conv(key); c.msgs.push(stampMsg({ f: 'sys', x: text })); }\nfunction toast(o) {\n  if (!wrap) return;\n  const box = phone && S.open ? $('.dp-toasts', phone) : $('.ph-toasts', wrap);\n  if (!box) return;\n  const n = el(`<button class=\"dp-toast\">${o.av || ''}<span><b>${esc(o.t)}</b><em>${esc(o.x)}</em></span><i class=\"dp-toast-o\"></i></button>`);\n  n.onclick = () => { n.remove(); if (o.go) { open(); go(o.go[0], o.go[1]); } };\n  box.appendChild(n); later(4600, () => { n.classList.add('bye'); later(400, () => n.remove()); });\n}\n\n/* ───────── 模型 ───────── */\n// 排队：同一时间只跑一个请求，避免并发把接口打满\nfunction ask(messages, o = {}) {\n  const run = () => H.generate(messages, Object.assign({ api: S.set.api, url: S.set.url, key: S.set.key, model: S.set.model }, o));\n  const p = S.queue.then(run, run);\n  S.queue = p.catch(() => null);\n  return p;\n}\nfunction cleanReply(t) {\n  return String(t || '').replace(/<think(?:ing)?>[\\s\\S]*?<\\/think(?:ing)?>/giu, '').replace(/^```\\w*\\n?|```$/gmu, '').trim();\n}\nconst brief = (s, n) => { s = String(s || '').replace(/\\s+/gu, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; };\n\n/* ───────── 世界书人设语料切片（按部、按外界日期匹配阶段） ───────── */\nconst BOOK_PARTS = ['斗1', '斗2', '神界', '英雄', '斗3', '斗4'];\nasync function warmPersonas() { try { if (H && typeof H.ensurePersonas === 'function') await H.ensurePersonas(); } catch (_) { /* 无世界书时略过 */ } }\nfunction ymKey(text, isEnd) {\n  const m = String(text == null ? '' : text).replace(/\\s/gu, '').replace(/^斗罗历/u, '').match(/^(前)?(\\d+)年(\\d{1,2})月(?:(\\d{1,2})日)?/u);\n  if (!m) return null;\n  const y = (m[1] ? -1 : 1) * Number(m[2]), mo = Number(m[3]), d = m[4] ? Number(m[4]) : (isEnd ? 31 : 1);\n  return y * 10000 + mo * 100 + d;\n}\nfunction lookupPersona(name, part) {\n  if (!H || typeof H.personaRaw !== 'function' || !name) return null;\n  const lib = W.DLAvatars;\n  const tries = [String(name).trim()];\n  if (lib) {\n    try {\n      const c = lib.canon && lib.canon(name, part); if (c && !tries.includes(c)) tries.push(c);\n      const id = lib.identity && lib.identity(name, part); if (id && !tries.includes(id)) tries.push(id);\n      for (const a of (lib.alsoKnownAs ? lib.alsoKnownAs(name, part) : [])) if (a && !tries.includes(a)) tries.push(a);\n    } catch (_) { /* 忽略别名异常 */ }\n  }\n  const idx = part ? BOOK_PARTS.indexOf(part) : -1;\n  const parts = idx >= 0 ? BOOK_PARTS.slice(0, idx + 1).reverse() : BOOK_PARTS;\n  for (const p of parts) {\n    for (const nm of tries) {\n      const key = `${nm}·${p}`;\n      const raw = H.personaRaw(key);\n      if (raw) return { key, raw };\n    }\n  }\n  return null;\n}\nfunction pickSec(blk, title) {\n  const m = new RegExp(`【${title}[^】]*】\\\\s*([\\\\s\\\\S]*?)(?=\\\\n【|\\\\n══|$)`, 'u').exec(blk);\n  return m ? m[1].trim() : '';\n}\nfunction pickField(blk, label) {\n  const m = new RegExp(`(?:^|\\\\n)${label}[：:]\\\\s*([\\\\s\\\\S]*?)(?=\\\\n[^\\\\n：:\\\\s]{2,10}[：:]|\\\\n【|\\\\n══|$)`, 'u').exec(blk);\n  return m ? m[1].trim() : '';\n}\nfunction pickBullets(blk, limit) {\n  const sec = blk ? blk.split(/\\n+/u).map((l) => l.trim()).filter((l) => /^[-•·]|^〔|^[“「]/u.test(l)) : [];\n  return sec.slice(0, limit);\n}\nfunction personaSlice(name, part, dateStr, mode = 'full') {\n  const hit = lookupPersona(name, part);\n  if (!hit) return '';\n  const body = String(hit.raw).replace(/\\r\\n/gu, '\\n').replace(/^<[^>]+>\\s*|\\s*<\\/[^>]+>$/gu, '').replace(/【档案信息】[\\s\\S]*?(?=\\n【)/u, '').trim();\n  if (!body) return '';\n  if (body.includes('【一句话人设】')) {\n    const one = pickSec(body, '一句话人设'), line = pickSec(body, '台词'), note = pickSec(body, '注解');\n    if (mode === 'compact') return `语感（${hit.key}）：${brief(one, 100)}${line ? ' ｜ 台词参考：' + brief(line, 110) : ''}`;\n    return `【人设与语料（${hit.key}）】\\n一句话人设：${brief(one, 260)}${line ? '\\n台词参考：' + brief(line, 200) : ''}${note ? '\\n补充：' + brief(note, 180) : ''}`;\n  }\n  const commonEnd = body.search(/\\n══\\s*阶段/u);\n  const common = commonEnd >= 0 ? body.slice(0, commonEnd) : (pickSec(body, '通用设定') || body);\n  const kw = pickField(common, '性格关键词');\n  const habit = pickField(common, '日常细节与反差');\n  const voice = pickField(common, '说话方式');\n  const redline = pickField(common, '扮演红线');\n\n  let stageTitle = '', stageBody = body;\n  const re = /══\\s*(阶段[一二三四五六][^═]*?)\\s*══（([^）]*)）/gu;\n  const headers = [...body.matchAll(re)];\n  if (headers.length) {\n    const stages = headers.map((m, i) => {\n      const startIdx = m.index + m[0].length;\n      const endIdx = i + 1 < headers.length ? headers[i + 1].index : body.length;\n      const parts = m[2].split(/至|—|-|~/u);\n      return { title: m[1].trim(), a: ymKey(parts[0], false), b: ymKey(parts[1] || parts[0], true), text: body.slice(startIdx, endIdx) };\n    });\n    const cur = ymKey(dateStr, false);\n    let chosen = stages[0];\n    if (cur != null) {\n      const exact = stages.find((s) => s.a != null && s.b != null && cur >= s.a && cur <= s.b);\n      if (exact) chosen = exact;\n      else if (stages[0].a != null && cur < stages[0].a) chosen = stages[0];\n      else { for (const s of stages) if (s.a != null && cur >= s.a) chosen = s; }\n    }\n    stageTitle = chosen.title;\n    stageBody = chosen.text;\n  }\n  const conflict = pickField(stageBody, '当前核心矛盾');\n  const v1 = pickBullets(pickSec(stageBody, '声部一'), mode === 'compact' ? 2 : 5);\n  const v2 = mode === 'compact' ? [] : pickBullets(pickSec(stageBody, '声部二'), 2);\n  if (mode === 'compact') {\n    const bits = [];\n    if (kw) bits.push(brief(kw, 55));\n    if (voice) {\n      const dmIdx = voice.indexOf('传讯口吻');\n      bits.push(dmIdx >= 0 ? brief(voice.slice(Math.max(0, dmIdx - 30)), 150) : brief(voice, 150));\n    }\n    if (v1.length) bits.push('原声例句：' + brief(v1.join(' / '), 140));\n    return bits.length ? `语感（${stageTitle || hit.key}）：${bits.join(' ｜ ')}` : '';\n  }\n  const out = [`【人设与语料（${hit.key}${stageTitle ? ' · ' + stageTitle : ''}）】`];\n  if (kw) out.push('性格关键词：' + brief(kw, 100));\n  if (habit) out.push('日常细节与反差：' + brief(habit, 220));\n  if (voice) out.push('说话与传讯口吻：' + brief(voice, 340));\n  if (redline) out.push('扮演红线：' + brief(redline, 180));\n  if (conflict) out.push('本阶段心境：' + brief(conflict, 140));\n  const quotes = [...v1, ...v2];\n  if (quotes.length) out.push('原声台词与心声参考：\\n' + quotes.map((q) => brief(q, 95)).join('\\n'));\n  return out.length > 1 ? out.join('\\n') : '';\n}\n\nfunction personCard(p) {\n  const r = p.raw || {};\n  const bits = [`${p.real}${p.name !== p.real ? `（此刻被叫作${p.name}）` : ''}`, r.性别, r.年龄 ? r.年龄 + '岁' : '', r.身份, r.势力 && r.势力 !== '无' ? r.势力 : '', p.title && p.lv ? `${p.title}${p.lv}级` : '', p.soul ? '武魂' + p.soul : ''].filter(Boolean).join('，');\n  return `${bits}。此刻在${p.where}，${p.doing}，情绪${p.mood}。对${D.hero.name}的好感 ${p.aff}（${affStage(p.aff)}）${p.love != null ? `，情意 ${p.love}` : ''}；关系：${(p.tags || []).join('、') || '一般'}。`;\n}\nfunction worldLine() { return `现在是${D.world.date}${D.world.place ? '，' + D.world.place : ''}${D.world.act ? '（原作进度：' + D.world.act + '）' : ''}。`; }\nfunction storyTail() { try { return brief(H.storyTail(2), 1400); } catch (_) { return ''; } }\n// 撤回：对方看到过的，记得内容；没看到的，只知道撤回了一条\nconst recallNote = (m, who) => (m.rc.seen ? `（撤回了一条消息；撤回前${who}已经看到了：${m.rc.k === 'img' ? `[图片：${m.rc.x || '一张照片'}]` : m.rc.x}）` : `（撤回了一条消息，${who}没来得及看到内容）`);\nconst asTurn = (m, selfId) => (m.f === 'sys' ? (m.rc ? { role: 'user', content: recallNote(m, '你') } : null) : { role: m.f === selfId ? 'assistant' : 'user', content: (m.f === 'me' ? '' : m.f !== selfId ? person(m.f).name + '：' : '') + (m.k === 'img' ? `[图片：${m.x || '一张照片'}]` : m.x) });\nfunction mergeTurns(list) { const out = []; for (const t of list.filter(Boolean)) { const last = out[out.length - 1]; if (last && last.role === t.role) last.content += '\\n' + t.content; else out.push({ role: t.role, content: t.content }); } if (!out.length || out[0].role !== 'user') out.unshift({ role: 'user', content: '（对话开始）' }); return out; }\nconst RULES_DM = (name, hero) => `像真人用手机发消息：口语、简短，一条一行，通常 1–3 条，最多 5 条；符合原作性格、此刻处境和与${hero}的关系，好感低就冷淡，好感高就亲近。\n只写${name}自己发出的消息文字：不替${hero}说话，不写动作描写和旁白，不加引号、不加名字前缀、不解释。\n想发图就单独一行写 [图片：画面描述]。被严重冒犯且好感已经很低时，可以单独一行写 [拉黑]。此刻不想回就只输出 [不回]。`;\nfunction promptDM(c, para) {\n  const p = c.p, hero = D.hero.name;\n  const lore = personaSlice(p.real, D.world.part, D.world.date, 'full');\n  const loreBlk = lore ? lore + '\\n' : '';\n  const sysText = para\n    ? `你在扮演《斗罗大陆》原作时间线里的「${p.real}」。那条时间线里没有${hero}，一切照原作发生；你只在“镜湖”里看到过另一条线上${hero}做的事，并不认识${hero}本人。现在${hero}跨线给你写信，你用魂导通讯器回复。\\n${worldLine()}\\n${loreBlk}${hero}在那条线上做过的事（你从镜湖看到的）：${paraFacts() || '还不多'}\\n${RULES_DM(p.real, hero)}`\n    : `你在扮演《斗罗大陆》里的「${p.real}」，正在用魂导通讯器（这个世界的手机）和${hero}私聊。\\n${worldLine()}\\n【${p.real}】${personCard(p)}\\n${loreBlk}【最近的正文（只作背景，手机那头的人不一定知道）】${storyTail() || '无'}\\n${p.state === 'busy' ? `你正在${p.doing}，抽空回，回得短。\\n` : ''}${RULES_DM(p.real, hero)}`;\n  const turns = mergeTurns(c.msgs.slice(-24).map((m) => asTurn(m, p.id)));\n  return [{ role: 'system', content: sysText }, ...turns];\n}\nfunction promptGroup(c, mention) {\n  const hero = D.hero.name;\n  const ms = c.members.map(person).filter((p) => ['ok', 'busy'].includes(p.state));\n  const memberLines = ms.map((p) => {\n    const lore = personaSlice(p.real, D.world.part, D.world.date, 'compact');\n    return `· ${personCard(p)}${lore ? '\\n  ' + lore : ''}`;\n  }).join('\\n');\n  const sysText = `这是魂导通讯器上的群聊「${c.name}」，成员有${hero}和：${c.members.map((id) => person(id).real).join('、')}。你负责写其他成员接下来的发言。\\n${worldLine()}\\n此刻能看手机的人：\\n${memberLines}\\n不在线（交战、昏迷等）的人不会说话。\\n【最近的正文（背景）】${storyTail() || '无'}\\n规则：按各自性格，挑 0–${S.set.maxGroup} 个人接话（被 @ 的人优先），可以互相接茬；每行一条，格式“名字：内容”，口语、简短；不替${hero}说话，不写旁白。没人想接话就只输出 [无人回复]。想发图写“名字：[图片：画面描述]”。${mention ? `\\n这次被点名的是：${mention.join('、')}。` : ''}`;\n  const turns = c.msgs.slice(-30).filter((m) => m.f !== 'sys' || m.rc).map((m) => (m.rc ? `${hero}：${recallNote(m, '群里的人')}` : `${m.f === 'me' ? hero : person(m.f).real}：${m.k === 'img' ? `[图片：${m.x || '一张照片'}]` : m.x}`)).join('\\n');\n  return [{ role: 'system', content: sysText }, { role: 'user', content: `群聊记录：\\n${turns}\\n\\n接下来其他人的发言：` }];\n}\nfunction paraFacts() {\n  const b = ents(stat && stat.蝴蝶效应).slice(-8).map(([, x]) => `${x.名称 || ''}：原作是“${brief(x.原作走向, 60)}”，这条线变成了“${brief(x.实际走向, 60)}”`);\n  return b.join('；');\n}\nfunction promptPara() {\n  const hero = D.hero.name;\n  const names = D.people.filter((p) => !p.paraOnly).map((p) => p.real).slice(0, 24);\n  const voices = names.slice(0, 8).map((nm) => { const s = personaSlice(nm, D.world.part, D.world.date, 'compact'); return s ? `· ${nm}：${s}` : ''; }).filter(Boolean).join('\\n');\n  const ev = ents(stat && stat.原作指导 && stat.原作指导.事件).slice(0, 8).map(([, e]) => `${e.日期 || ''} ${e.标题 || ''}（${e.状态 || ''}）`).join('；');\n  const sysText = `“平行线”：另一条时间线完全照《斗罗大陆》原作发生，那里没有${hero}。那边的人能通过“镜湖”看到这条线上${hero}做的事，并在镜湖论坛上议论、评价。\\n${worldLine()}\\n可以发帖、评论的人（原作时间线里的他们）：${names.join('、') || '原作人物'}，也可以是匿名者（写 anon）。\\n${voices ? `代表人物语感参考：\\n${voices}\\n` : ''}这条线上${hero}改变了的事（蝴蝶效应）：${paraFacts() || '暂无记录'}\\n原作此时的事件：${ev || '无'}\\n【这条线最近的正文】${storyTail() || '无'}\\n只输出一个 JSON 对象，不要别的文字：{\"posts\":[{\"tag\":\"观测|蝴蝶|闲聊|匿名\",\"by\":\"人名或null\",\"anon\":\"匿名时的署名\",\"title\":\"标题\",\"body\":\"正文，可分行\",\"comments\":[{\"by\":\"人名\",\"x\":\"评论\"}]}],\"verdicts\":[{\"act\":\"${hero}最近做的一件事（一句话）\",\"says\":[{\"by\":\"人名\",\"tone\":\"赞|嗤|叹|疑|怒|笑\",\"x\":\"评价\"}]}]}\\n帖子 1–2 篇、每篇 2–4 条评论；评说 1 条、2–4 个人。用原作性格说话，紧扣${hero}最近的所作所为，别重复旧帖：${store.para.posts.slice(0, 5).map((p) => p.title).join('、') || '无'}。`;\n  return [{ role: 'system', content: sysText }, { role: 'user', content: '镜湖又起波纹了。' }];\n}\nfunction promptPost(c, myText) {\n  const hero = D.hero.name;\n  const active = [...new Set([c.by, ...c.cms.map((x) => x.by)].filter((b) => b && b !== 'me'))].slice(0, 6);\n  const voices = active.map((id) => { const nm = person(id).real; const s = personaSlice(nm, D.world.part, D.world.date, 'compact'); return s ? `· ${nm}：${s}` : ''; }).filter(Boolean).join('\\n');\n  const sysText = `镜湖论坛：原作时间线（没有${hero}）里的人在议论另一条线上的${hero}。现在那条线的${hero}本人跨线回帖了，大家会有反应。\\n帖子《${c.title}》：${brief(c.body, 400)}\\n已有回帖：\\n${c.cms.slice(-10).map((x) => `${x.by === 'me' ? hero + '（本人）' : x.by ? person(x.by).real : x.anon || '匿名'}：${x.x}`).join('\\n')}\\n${voices ? `在场人物语感参考：\\n${voices}\\n` : ''}写 1–3 条新回帖，每行“名字：内容”，原作性格、简短。不替${hero}说话。`;\n  return [{ role: 'system', content: sysText }, { role: 'user', content: `${hero}（本人）回帖：${myText}` }];\n}\nfunction parseLines(text, mode, members) {\n  const t = cleanReply(text);\n  const out = { lines: [], block: /\\[拉黑\\]/u.test(t), none: /\\[(不回|无人回复)\\]/u.test(t) };\n  for (let line of t.split(/\\n+/u)) {\n    line = line.trim().replace(/^[-*·•]\\s*/u, '');\n    if (!line || /^\\[(拉黑|不回|无人回复)\\]$/u.test(line)) continue;\n    let by = null;\n    if (mode === 'group' || mode === 'post') {\n      const m = /^([^：:\\s]{1,12})[：:]\\s*(.+)$/u.exec(line);\n      if (!m) continue;\n      by = matchName(m[1], members);\n      if (!by) continue;\n      line = m[2].trim();\n    } else line = line.replace(/^[^：:\\s]{1,8}[：:]\\s*/u, (pre) => (members && members.some((n) => pre.startsWith(n)) ? '' : pre));\n    line = line.replace(/^[\"“「『]|[\"”」』]$/gu, '').trim();\n    if (!line) continue;\n    const img = /^\\[(?:图片|图)[：:]\\s*(.+?)\\]$/u.exec(line);\n    out.lines.push(img ? { by, k: 'img', x: img[1], pic: picOf(img[1]) } : { by, x: line.replace(/\\[拉黑\\]|\\[不回\\]/gu, '').trim() });\n  }\n  out.lines = out.lines.filter((l) => l.x).slice(0, mode === 'group' ? 12 : 6);\n  return out;\n}\nfunction matchName(n, members) {\n  const s = String(n).trim();\n  const lib = W.DLAvatars;\n  for (const id of members || []) { const p = person(id); if (s === id || s === p.name || s === p.real) return id; }\n  for (const id of members || []) { const p = person(id); if (id.includes(s) || s.includes(id) || (p.name && (p.name.includes(s) || s.includes(p.name)))) return id; }\n  if (lib && typeof lib.canon === 'function') { try { const c = lib.canon(s, D.world.part); if (c && (members || []).includes(c)) return c; } catch (_) { /* 认不出 */ } }\n  return null;\n}\nconst errText = (e) => brief((e && (e.message || e.toString())) || '未知错误', 60);\n// 一行一行地“打”出来\nfunction deliver(key, pid, lines, i0 = 0) {\n  const e = epoch;\n  return new Promise((done) => {\n    let i = 0;\n    const step = () => {\n      if (i >= lines.length || stale(e)) { done(); return; }\n      const l = lines[i++], who = l.by || pid;\n      typing(key, who, true);\n      after(Math.min(2600, 500 + String(l.x || '').length * 45) + (i === 1 ? i0 : 0), () => { if (stale(e)) { done(); return; } typing(key, who, false); push(key, Object.assign({ f: who, x: l.x }, l.k ? { k: l.k, pic: l.pic } : {})); after(rnd(250, 600), step); });\n    };\n    step();\n  });\n}\n\n/* ───────── 发送 ───────── */\nconst pending = {}; // 连发合并：最后一条之后等一会儿再请模型\nfunction send(key, payload) {\n  const c = conv(key);\n  if (c.type === 'post') { push(key, { by: 'me', x: payload.x }); replyPost(key, payload.x); return; }\n  const m = push(key, Object.assign({ f: 'me', st: 'sending', at: Date.now() }, payload));\n  after(300, () => {\n    if (m.f !== 'me' || !c.msgs.includes(m)) return; // 这 300ms 里撤回或删掉了\n    if (c.type === 'pdm') { setSt(m, 'sent'); schedule(key, () => replyDM(key, true)); return; }\n    if (c.type === 'group') { setSt(m, 'sent'); schedule(key, () => replyGroup(key)); return; }\n    const p = c.p;\n    if (['dead', 'gone'].includes(p.state)) { setSt(m, 'fail'); after(400, () => sys(key, p.state === 'dead' ? `${p.name} 的魂印已沉寂。消息不会再有人接收。` : `联系不上 ${p.name}。`)); return; }\n    if (p.state === 'block') { setSt(m, 'block'); after(400, () => sys(key, '消息已发出，但被对方拒收了。')); return; }\n    if (S.set.noReply && p.state === 'fight') { setSt(m, 'unseen'); after(400, () => sys(key, p.name + ' 正在交战，魂力波动剧烈，暂时不会回复。')); return; }\n    if (S.set.noReply && p.state === 'coma') { setSt(m, 'unseen'); after(400, () => sys(key, p.name + ' 失去意识，消息送到了，但没有人看。')); return; }\n    if (S.set.block && p.aff <= -51 && Math.random() < Math.min(0.85, 0.25 + (-p.aff - 51) / 160)) { doBlock(p, m); return; }\n    setSt(m, 'sent');\n    if (p.state === 'busy') after(500, () => sys(key, p.name + ' 在修炼，看到了会回，可能要等一阵。'));\n    schedule(key, () => replyDM(key, false), p.state === 'busy' ? 7000 : 1300);\n  });\n}\n/* ───────── 撤回、重发 ─────────\n   · 对方还没看到的（发送中、已送达还没回、未读、未送达、被拒收）随时能撤回；已经看到的（已读，或 TA 正在输入回复）只有发出后 2 分钟内能撤回，而且 TA 记得内容。\n   · 撤回后那条变成“你撤回了一条消息”，文字消息可以“重新编辑”放回输入框；撤回后这段对话没有等回复的消息了，就取消排着的回复（不白花一次请求）。\n   · 重发：未送达、被拒收、未读的，挪到最下面重新走一遍发送（对方状态变了结果就不同），不留两份；已读的“再发”是再发一份。 */\nconst RECALL_MS = 120000, WAITING = ['sending', 'sent'], UNDELIVERED = ['fail', 'block', 'unseen'];\nconst inflight = new WeakSet(); // 正在等模型回复时带上的那几条：TA 已经在看、在打字了\nconst seenBy = (m) => m.st === 'read' || inflight.has(m);\nfunction recallable(m) { return m.f === 'me' && (!seenBy(m) || (typeof m.at === 'number' && Date.now() - m.at < RECALL_MS)); }\n// 这段对话已经没有等回复的消息了：取消排着的回复\nfunction settle(key) {\n  const c = conv(key);\n  if (pending[key] && !c.msgs.some((z) => z.f === 'me' && WAITING.includes(z.st))) { clearTimeout(pending[key]); delete pending[key]; }\n}\nfunction recall(c, m) {\n  if (m.f !== 'me' || !c.msgs.includes(m)) return false;\n  const seen = seenBy(m);\n  if (!recallable(m)) { toast({ t: '撤回', x: '发出超过 2 分钟，对方已经看过了，撤不回了。' }); return false; }\n  const rc = { x: m.x || '', seen };\n  if (m.k === 'img') rc.k = 'img';\n  ['st', 'k', 'src', 'pic', 'at'].forEach((f) => { delete m[f]; });\n  Object.assign(m, { f: 'sys', x: '你撤回了一条消息', rc });\n  settle(c.key); redraw(m); save(); refreshTops();\n  return true;\n}\nfunction resend(c, m) {\n  if (m.f !== 'me' || !c.msgs.includes(m)) return false;\n  if (WAITING.includes(m.st)) { toast({ t: '重发', x: '这条还在等对方回，不用重发。' }); return false; }\n  const payload = { x: m.x };\n  if (m.k === 'img') Object.assign(payload, { k: 'img' }, m.src ? { src: m.src } : { pic: m.pic || picOf(m.x) });\n  if (UNDELIVERED.includes(m.st)) { c.msgs.splice(c.msgs.indexOf(m), 1); if (phone) $$(`[data-mid=\"${m.id}\"]`, phone).forEach((n) => n.remove()); }\n  send(c.key, payload);\n  return true;\n}\nfunction schedule(key, fn, wait = 1300) {\n  if (pending[key]) clearTimeout(pending[key]);\n  pending[key] = later(wait, () => { delete pending[key]; fn(); });\n}\nfunction doBlock(p, m) {\n  store.blocked[p.id] = { at: D.world.date, aff: p.aff };\n  if (m) setSt(m, 'block');\n  sys('dm:' + p.id, `${p.name} 把你拉黑了。`);\n  p.state = 'block'; p.stateText = '已将你拉黑';\n  toast({ av: av(p, 'sm'), t: `${p.name} 把你拉黑了`, x: `好感「${affStage(p.aff)}」。之后发的消息会被拒收，好感回到「陌路」才会放出来。`, go: ['chat', 'dm:' + p.id] });\n  save(); refreshAll();\n}\nasync function replyDM(key, para) {\n  const c = conv(key), p = c.p;\n  if (S.busy.has(key)) { schedule(key, () => replyDM(key, para), 1500); return; }\n  S.busy.add(key);\n  const mine = c.msgs.filter((m) => m.f === 'me' && (m.st === 'sent' || m.st === 'sending'));\n  mine.forEach((m) => inflight.add(m));\n  typing(key, p.id, true);\n  const e = epoch;\n  try {\n    await warmPersonas();\n    const raw = await ask(promptDM(c, para), { tag: para ? 'para-dm' : 'dm', max: 500 });\n    if (stale(e)) return;\n    typing(key, p.id, false);\n    const r = parseLines(raw, 'dm', [p.id, p.name, p.real]);\n    mine.forEach((m) => setSt(m, 'read'));\n    if (r.none || !r.lines.length) { if (!para) after(600, () => sys(key, `${p.name} 看了消息，没有回。`)); }\n    else await deliver(key, p.id, r.lines);\n    if (!para && r.block && S.set.block && p.aff <= -21) doBlock(p, null);\n  } catch (err) {\n    if (stale(e)) return;\n    typing(key, p.id, false);\n    mine.forEach((m) => setSt(m, 'fail'));\n    sys(key, `消息没送出去：${errText(err)}。点＋里的“催一下”可以再试。`);\n  } finally { mine.forEach((m) => inflight.delete(m)); if (!stale(e)) S.busy.delete(key); }\n}\nasync function replyGroup(key) {\n  const c = conv(key);\n  if (S.busy.has(key)) { schedule(key, () => replyGroup(key), 1500); return; }\n  const able = c.members.filter((id) => ['ok', 'busy'].includes(person(id).state));\n  const mine = c.msgs.filter((m) => m.f === 'me' && (m.st === 'sent' || m.st === 'sending'));\n  if (!able.length) { mine.forEach((m) => setSt(m, 'read')); after(1500, () => sys(key, '群里的人此刻都顾不上看手机。')); return; }\n  S.busy.add(key);\n  mine.forEach((m) => inflight.add(m));\n  const lastMine = mine.slice(-1)[0];\n  const mention = lastMine ? c.members.filter((id) => { const p = person(id); return lastMine.x && (lastMine.x.includes('@' + p.name) || lastMine.x.includes('@' + id)); }).map((id) => person(id).real) : [];\n  const e = epoch;\n  try {\n    await warmPersonas();\n    const raw = await ask(promptGroup(c, mention.length ? mention : null), { tag: 'group', max: 700 });\n    if (stale(e)) return;\n    const r = parseLines(raw, 'group', able);\n    mine.forEach((m) => setSt(m, 'read'));\n    const lines = r.lines.filter((l) => able.includes(l.by));\n    const speakers = [...new Set(lines.map((l) => l.by))].slice(0, S.set.maxGroup);\n    const keep = lines.filter((l) => speakers.includes(l.by));\n    if (!keep.length) after(1600, () => sys(key, '群里安静了一会儿，没有人接话。'));\n    else await deliver(key, keep[0].by, keep, 300);\n  } catch (err) {\n    if (stale(e)) return;\n    mine.forEach((m) => setSt(m, 'fail'));\n    sys(key, `群消息没送出去：${errText(err)}`);\n  } finally { mine.forEach((m) => inflight.delete(m)); if (!stale(e)) S.busy.delete(key); }\n}\nasync function replyPost(key, myText) {\n  const c = conv(key);\n  const names = [...new Set([...D.people.filter((p) => !p.paraOnly).map((p) => p.id), ...c.cms.map((x) => x.by).filter((b) => b && b !== 'me')])];\n  const e = epoch;\n  try {\n    await warmPersonas();\n    const raw = await ask(promptPost(c, myText), { tag: 'post', max: 500 });\n    if (stale(e)) return;\n    const r = parseLines(raw, 'post', names);\n    r.lines.slice(0, 3).forEach((l, i) => after(1200 + i * 1500, () => { if (!stale(e)) push(key, { by: l.by, x: l.x, tm: '刚刚' }); }));\n  } catch (err) { if (!stale(e)) toast({ t: '镜湖', x: '回帖没传到彼端：' + errText(err) }); }\n}\nfunction parseJson(t) {\n  const s = cleanReply(t), a = s.indexOf('{'), b = s.lastIndexOf('}');\n  if (a < 0 || b < a) throw new Error('模型没有按格式回');\n  return JSON.parse(s.slice(a, b + 1));\n}\n// 原线的人：认得的归到名册里的人，认不出的记成只在平行线出现的人\nfunction paraWho(n) {\n  if (!n || n === 'null') return null;\n  const hit = matchName(n, D.people.map((p) => p.id));\n  if (hit) return hit;\n  const s = String(n).trim().slice(0, 12);\n  if (!s) return null;\n  if (!byId[s]) { const o = ghost(s); o.state = 'ok'; o.paraOnly = true; D.people.push(o); byId[s] = o; }\n  return s;\n}\n\n/* ───────── 主动消息：正文推进几层后，有人主动来找你（私聊、群聊、原线来信） ───────── */\nconst ABLE = ['ok', 'busy'];\nconst shuffle = (a) => a.map((x) => [Math.random(), x]).sort((p, q) => p[0] - q[0]).map((x) => x[1]);\nfunction proCandidates() {\n  const lastFloorOf = (key) => { const c = store.convs[key]; const m = c && c.msgs.filter((x) => x.f !== 'sys').slice(-1)[0]; return m && m.floor != null ? m.floor : null; };\n  // 好感、情意越高越可能来找；最近聊过的更可能；人就在身边的不太会发消息\n  const score = (p) => { const last = lastFloorOf('dm:' + p.id); return 1 + Math.max(-0.6, p.aff / 80) + (p.love || 0) / 40 + (last != null && floorNow - last < 12 ? 0.8 : 0) - (p.here ? 0.6 : 0) + Math.random() * 1.2; };\n  const dms = D.people.filter((p) => !p.paraOnly && ABLE.includes(p.state) && store.known[p.id] && !S.busy.has('dm:' + p.id))\n    .map((p) => [score(p), p]).sort((a, b) => b[0] - a[0]).slice(0, 4).map((x) => x[1]);\n  const groups = shuffle(store.groups.filter((g) => !S.busy.has('g:' + g.id) && (g.members || []).some((id) => ABLE.includes(person(id).state)))).slice(0, 2);\n  const paras = S.set.paraPro ? shuffle([...new Set([...Object.keys(store.para.dms), ...D.people.filter((p) => !p.paraOnly && p.state !== 'none').map((p) => p.id)])]).slice(0, 3) : [];\n  return { dms, groups, paras };\n}\nfunction promptPro(c) {\n  const hero = D.hero.name;\n  const recent = (key, n) => conv(key).msgs.filter((m) => m.f !== 'sys').slice(-n).map((m) => `${m.f === 'me' ? hero : person(m.f).real}：${m.k === 'img' ? '[图片]' : brief(m.x, 60)}`).join(' / ') || '（还没聊过）';\n  const lines = [];\n  c.dms.forEach((p) => {\n    const lore = personaSlice(p.real, D.world.part, D.world.date, 'compact');\n    lines.push(`· 私聊｜${personCard(p)}${lore ? '\\n  ' + lore : ''}\\n  最近的消息：${recent('dm:' + p.id, 4)}`);\n  });\n  c.groups.forEach((g) => {\n    const able = g.members.filter((id) => ABLE.includes(person(id).state)).map((id) => person(id).real);\n    const voices = able.slice(0, 4).map((nm) => { const s = personaSlice(nm, D.world.part, D.world.date, 'compact'); return s ? `    ${nm}：${s}` : ''; }).filter(Boolean).join('\\n');\n    lines.push(`· 群聊「${g.name}」｜此刻能看手机的成员：${able.join('、')}${voices ? '\\n' + voices : ''}\\n  最近的消息：${recent('g:' + g.id, 5)}`);\n  });\n  c.paras.forEach((id) => {\n    const nm = person(id).real;\n    const lore = personaSlice(nm, D.world.part, D.world.date, 'compact');\n    lines.push(`· 原线｜${nm}（原作时间线里的 TA：那条线没有${hero}，只在镜湖里见过${hero}做的事）${lore ? '\\n  ' + lore : ''}\\n  最近的来信：${store.para.dms[id] ? recent('pd:' + id, 3) : '（还没通过信）'}`);\n  });\n  const sysText = `你在安排《斗罗大陆》魂导通讯器（手机）上的“主动消息”：正文又推进了几层，看看有没有人会主动来找${hero}。\\n${worldLine()}\\n【最近的正文】${storyTail() || '无'}\\n${c.paras.length ? `【这条线上${hero}改变了的事】${paraFacts() || '暂无记录'}\\n` : ''}候选（只能从这里挑）：\\n${lines.join('\\n')}\\n规则：挑 0–2 个此刻最有理由开口的（被正文里的事触动、惦记、有事要说、来打听、来挑衅都行；没人有理由就一个都不发）。按原作性格、此刻处境和与${hero}的关系说话：口语、简短，每个 1–3 行；不替${hero}说话，不写旁白和动作描写。群聊每行写“名字：内容”，可以几个人接茬。想发图单独一行写 [图片：画面描述]。\\n只输出一个 JSON 对象：{\"msgs\":[{\"ch\":\"私聊|群聊|原线\",\"who\":\"人名（私聊、原线填）\",\"group\":\"群名（群聊填）\",\"lines\":[\"…\"]}]}；没人发就输出 {\"msgs\":[]}`;\n  return [{ role: 'system', content: sysText }, { role: 'user', content: '这会儿有谁会发来消息？' }];\n}\nasync function runProactive(manual) {\n  if (S.busy.has('pro') || !stat) return;\n  const c = proCandidates();\n  if (!c.dms.length && !c.groups.length && !c.paras.length) { if (manual) toast({ t: '主动消息', x: '现在没有能主动联系你的人（先在正文里和人交换联系方式）。' }); return; }\n  S.busy.add('pro');\n  store.proLast = floorNow;\n  const e = epoch;\n  try {\n    await warmPersonas();\n    const j = parseJson(await ask(promptPro(c), { tag: 'pro', max: 900 }));\n    if (stale(e)) return;\n    let n = 0;\n    for (const it of (Array.isArray(j.msgs) ? j.msgs : []).slice(0, 2)) {\n      if (!it || typeof it !== 'object') continue;\n      const raw = (Array.isArray(it.lines) ? it.lines : [it.lines]).filter(Boolean).map(String).join('\\n');\n      const ch = String(it.ch || ''), gname = String(it.group || '');\n      if (/群/u.test(ch)) {\n        const g = c.groups.find((x) => x.name === gname) || c.groups.find((x) => gname && (gname.includes(x.name) || x.name.includes(gname))) || (c.groups.length === 1 ? c.groups[0] : null);\n        if (!g) continue;\n        const able = g.members.filter((id) => ABLE.includes(person(id).state));\n        const lines = parseLines(raw, 'group', able).lines.filter((l) => able.includes(l.by));\n        if (lines.length) { n += 1; await deliver('g:' + g.id, lines[0].by, lines); }\n      } else if (/原|彼端|平行/u.test(ch)) {\n        const id = paraWho(it.who);\n        if (!id) continue;\n        const lines = parseLines(raw, 'dm', [id, person(id).name]).lines;\n        if (lines.length) { n += 1; conv('pd:' + id); await deliver('pd:' + id, id, lines); }\n      } else {\n        const p = c.dms.find((x) => matchName(it.who, [x.id]));\n        if (!p) continue;\n        const lines = parseLines(raw, 'dm', [p.id, p.name, p.real]).lines;\n        if (lines.length) { n += 1; await deliver('dm:' + p.id, p.id, lines); }\n      }\n    }\n    if (manual && !n) toast({ t: '主动消息', x: '这会儿没人想主动找你。' });\n    save();\n  } catch (err) { if (stale(e)) return; if (manual) toast({ t: '主动消息', x: '没生成出来：' + errText(err) }); else console.warn('[斗罗小手机] 主动消息失败', err); }\n  finally { if (!stale(e)) { S.busy.delete('pro'); refreshTops(); } }\n}\n\nasync function refreshPara(manual) {\n  if (S.busy.has('para') || !stat) return;\n  S.busy.add('para'); if (manual) refreshTops();\n  const e = epoch;\n  try {\n    await warmPersonas();\n    const j = parseJson(await ask(promptPara(), { tag: 'para', max: 1600 }));\n    if (stale(e)) return;\n    const P = store.para, norm = paraWho;\n    (Array.isArray(j.posts) ? j.posts : []).slice(0, 2).reverse().forEach((p) => {\n      P.posts.unshift({ id: 'p' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5), tag: String(p.tag || '观测').slice(0, 4), by: norm(p.by), anon: p.anon || (p.by ? '' : '匿名'), title: String(p.title || '无题'), body: String(p.body || ''), tm: '刚刚', views: Math.floor(rnd(80, 3200)) + '', hot: Math.random() < 0.35,\n        cms: (Array.isArray(p.comments) ? p.comments : []).slice(0, 6).map((x) => ({ by: norm(x.by), x: String(x.x || ''), tm: '刚刚' })).filter((x) => x.x) });\n    });\n    (Array.isArray(j.verdicts) ? j.verdicts : []).slice(0, 2).forEach((v) => {\n      P.verdicts.unshift({ act: String(v.act || '你最近做的事'), floor: `第 ${floorNow} 层`, says: (Array.isArray(v.says) ? v.says : []).slice(0, 5).map((s) => ({ by: norm(s.by), tone: String(s.tone || '叹').slice(0, 1), x: String(s.x || '') })).filter((s) => s.x) });\n      P.fresh = (P.fresh || 0) + 1;\n    });\n    P.posts = P.posts.slice(0, 40); P.verdicts = P.verdicts.slice(0, 30); P.lastFloor = floorNow;\n    save();\n    toast({ t: '平行线 · 镜湖', x: '彼端又有人议论你了。', go: ['parallel', null] });\n  } catch (err) { if (stale(e)) return; if (manual) toast({ t: '镜湖', x: '这次没看清彼端：' + errText(err) }); else console.warn('[斗罗小手机] 镜湖更新失败', err); }\n  finally { if (!stale(e)) { S.busy.delete('para'); refreshTops(); } }\n}\nasync function regen(key, mid) {\n  const c = conv(key), i = c.msgs.findIndex((m) => m.id === mid);\n  if (i < 0 || c.type === 'post') return;\n  const m = c.msgs[i], tail = c.msgs.slice(0, i);\n  const fake = Object.create(c); def(fake, 'msgs', tail); def(fake, 'p', c.p);\n  const e = epoch;\n  try {\n    await warmPersonas();\n    let lines;\n    if (c.type === 'group') { const r = parseLines(await ask(promptGroup(Object.assign(fake, { members: c.members, name: c.name }), [person(m.f).real]), { tag: 'regen', max: 300 }), 'group', [m.f]); lines = r.lines.filter((l) => l.by === m.f); }\n    else lines = parseLines(await ask(promptDM(fake, c.type === 'pdm'), { tag: 'regen', max: 300 }), 'dm', [m.f]).lines;\n    if (stale(e)) return;\n    if (!lines || !lines.length) return toast({ t: '重说', x: 'TA 这次什么也没说。' });\n    Object.assign(m, { x: lines[0].x, k: lines[0].k, pic: lines[0].pic });\n    if (!lines[0].k) { delete m.k; delete m.pic; }\n    save(); refreshAll();\n  } catch (err) { if (!stale(e)) toast({ t: '重说', x: errText(err) }); }\n}\n\n/* ───────── 写进正文（注入） ───────── */\nfunction buildInject() {\n  if (!S.set.inject || !store) return '';\n  const hero = D.hero.name, recent = floorNow - 6;\n  const parts = [];\n  for (const key of store.order) {\n    const c = conv(key);\n    const msgs = c.msgs.filter((m) => m.f !== 'sys');\n    if (!msgs.length || (msgs[msgs.length - 1].floor != null && msgs[msgs.length - 1].floor < recent)) continue;\n    const head = c.type === 'group' ? `群聊「${c.name}」（${c.members.map((id) => person(id).real).join('、')}）` : `与${c.p.real}的私聊`;\n    const lines = msgs.slice(-S.set.per).map((m) => `${m.f === 'me' ? hero : person(m.f).real}：${m.k === 'img' ? `[图片：${m.x || '照片'}]` : m.x}${m.f === 'me' && ['block', 'fail', 'unseen'].includes(m.st) ? `（${ST[m.st]}）` : ''}`);\n    parts.push(`· ${head}\\n${lines.map((l) => '  ' + l).join('\\n')}`);\n    if (parts.length >= 6) break;\n  }\n  if (!parts.length) return '';\n  return `【魂导通讯器】${hero}和其他人最近在通讯器（手机）上的消息。消息双方都知道这些内容，正文可以自然承接、提及；不要复述整段记录。\\n${parts.join('\\n')}`;\n}\nlet lastInject = null;\nfunction inject() {\n  const text = buildInject();\n  const sig = text + '|' + S.set.depth;\n  if (sig === lastInject) return;\n  lastInject = sig;\n  try { H.inject(text || null, S.set.depth); } catch (e) { console.warn('[斗罗小手机] 写进正文失败', e); }\n}\n\n/* ───────── 顶栏、动效 ───────── */\nconst ZHI = '子丑寅卯辰巳午未申酉戌亥';\nfunction tops(n) {\n  return store.order.map(conv).filter((c) => c.unread).slice(0, n).map((c) => { const g = c.type === 'group', last = c.msgs[c.msgs.length - 1];\n    return { go: (g ? 'group' : 'chat') + ':' + c.key, face: g ? `<span class=\"dp-gav\">${c.members.slice(0, 4).map((i) => av(i, 'xs')).join('')}</span>` : av(c.p, 'sm'), name: g ? c.name : c.p.name, text: preview(c), tm: (last && last.tm) || '', n: c.unread }; });\n}\nfunction ctx() {\n  const d = new Date(), h = d.getHours(), m = d.getMinutes(), ke = Math.floor(m / 15);\n  return { hh: String(h).padStart(2, '0'), mm: String(m).padStart(2, '0'), hm: now(), shichen: ZHI[Math.floor(((h + 1) % 24) / 2)] + (h % 2 ? '初' : '正') + (ke ? ['', '一刻', '二刻', '三刻'][ke] : ''),\n    date: esc(D.world.date), md: esc(D.world.md), act: esc(D.world.act || '——'), place: esc(D.world.place), soul: Math.round(D.hero.魂力), sig: stat ? 4 : 1, unread: unreadMsg(), hero: D.hero, world: D.world, ic, av, D, unreadPara: unreadPara() };\n}\nfunction paintSb() { if (sbEl && S.opts && S.opts.statusbar && S.opts.statusbar[S.theme]) { try { sbEl.innerHTML = S.opts.statusbar[S.theme](ctx()); } catch (e) { console.warn('[斗罗小手机] 顶栏', e); } } }\nfunction tickSb() {\n  if (!phone) return;\n  const c = ctx(); $$('[data-sb]', phone).forEach((n) => { const k = n.dataset.sb; if (c[k] != null && n.textContent !== String(c[k])) n.textContent = c[k]; });\n  $$('[data-lat]', phone).forEach((e) => { e.textContent = 9 + Math.floor(Math.random() * 16); }); // 星际联邦的“延迟”读数\n}\n// 背景动效画布。手机上（窄屏或触屏）地址栏收放、键盘、回弹都会让画布连着变尺寸：\n// 以前每变一次就把粒子重新随机撒一遍、还先清空一帧，连起来就是满屏乱跳。现在：\n// 粒子只在换主题时重撒（坐标本来就是按比例存的，变尺寸照画即可）；变尺寸当场补画一帧，不留空白帧；\n// 手机上降分辨率、降到约 24 帧，手指按着或正在滑动时先停住不画。\nconst isLow = () => { try { return W.innerWidth <= 760 || W.matchMedia('(pointer:coarse)').matches; } catch (_) { return false; } };\nlet touchAt = 0, touching = false, fxSeeds = 0;\nfunction fxLoop(cv) {\n  const g = cv.getContext('2d'); let Wd = 0, Ht = 0, last = 0, fx = null, of = null, clean = false, dead = false;\n  let low = isLow(); // 窄屏、触屏：每次变尺寸时重看一次（转屏、拖窗口）\n  const live = () => !DOC.hidden && S.open && curMotion === 'full' && Wd > 0;\n  const paint = (t) => {\n    if (of !== S.theme) { of = S.theme; fxSeeds += 1; const f = S.opts.fx && S.opts.fx[S.theme]; try { fx = f ? f(Wd, Ht) : null; } catch (_) { fx = null; } }\n    const dt = last ? Math.min(0.1, Math.max(0, t - last) / 1000) : 0; last = t; clean = false;\n    g.clearRect(0, 0, Wd, Ht); if (fx) { try { fx(g, Wd, Ht, t / 1000, dt); } catch (_) { fx = null; } }\n  };\n  const size = () => {\n    low = isLow();\n    const r = cv.getBoundingClientRect(), d = Math.min(low ? 1.5 : 2, W.devicePixelRatio || 1);\n    const pw = Math.round(r.width * d), ph = Math.round(r.height * d);\n    Wd = r.width; Ht = r.height;\n    if (pw === cv.width && ph === cv.height) return;\n    cv.width = pw; cv.height = ph; g.setTransform(d, 0, 0, d, 0, 0); // 改画布尺寸会清空：当场补画，免得闪一帧空白\n    if (live()) paint(W.performance.now()); else clean = true;\n  };\n  const ro = new W.ResizeObserver(size); ro.observe(cv); size();\n  const frame = (t) => {\n    if (dead || !cv.isConnected) { ro.disconnect(); return; }\n    requestAnimationFrame(frame);\n    if (!live()) { if (!clean) { g.clearRect(0, 0, Wd, Ht); clean = true; } last = 0; return; }\n    if (touching && t - touchAt > 8000) touching = false; // 漏了松手事件也别一直停着\n    if (low && (touching || t - touchAt < 260)) { last = t; return; } // 手指在屏上、刚滑完：停在当前这帧\n    if (t - last < (low ? 41 : 33)) return;\n    paint(t);\n  };\n  requestAnimationFrame(frame);\n  return () => { dead = true; ro.disconnect(); };\n}\n\n/* ───────── 交互 ───────── */\nfunction setTheme(id) {\n  const t = S.themes.find((x) => x.id === id);\n  if (!t) return;\n  S.set.theme = id; saveSet();\n  if (t.shell !== S.shell) { buildPhone(); return; }\n  S.theme = id; phone.dataset.theme = id;\n  phone.classList.remove('swap'); void phone.offsetWidth; phone.classList.add('swap');\n  paintSb(); navs().forEach((n) => { if (n.cur && n.cur.name === 'settings') n.refresh(); });\n  if (S.opts.onTheme) try { S.opts.onTheme(id, phone); } catch (_) { /* 主题自己的小动作 */ }\n}\nfunction setMotion(m) { S.set.motion = m; saveSet(); syncMotion(); navs().forEach((n) => { if (n.cur && n.cur.name === 'settings') n.refresh(); }); }\nasync function act(a, t) {\n  const i = a.indexOf(':'), k = i < 0 ? a : a.slice(0, i), rest = i < 0 ? '' : a.slice(i + 1);\n  const [